INSERT INTO _n1_b4_guard_0103(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-11-12' AND '2026-11-25' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1347','2026-11-12','見渡す','みわたす','둘러보다; 멀리까지 바라보다','高い所や広い場所などから、周囲や遠くまで広く眺める。','展望台から市街地を見渡すと、川の流れまでよく見えた。','전망대에서 시가지를 둘러보니 강의 흐름까지 잘 보였다.'),
('n1-1353','2026-11-12','勤勉','きんべん','근면함; 성실히 노력함','仕事・勉強などにまじめに励み、怠けず努力を続けるさま。','彼は勤勉な姿勢を評価され、重要な業務を任された。','그는 근면한 태도를 평가받아 중요한 업무를 맡았다.'),
('n1-1356','2026-11-12','肝心','かんじん','가장 중요함; 핵심','物事の中で最も重要で、欠かすことのできないさま。','機能を増やすことより、肝心なのは安定して動くことだ。','기능을 늘리는 것보다 중요한 것은 안정적으로 동작하는 것이다.'),
('n1-1359','2026-11-12','残酷','ざんこく','잔혹함; 무자비함','人や動物に対して情けがなく、ひどく苦しめるようなさま。','戦争が市民にもたらした残酷な現実が記録に残されている。','전쟁이 시민에게 가져온 잔혹한 현실이 기록에 남아 있다.'),
('n1-1364','2026-11-12','練る','ねる','다듬다; 숙고하다; 반죽하다','材料をこねて均一にする。また、計画・文章・考えなどを十分に検討して仕上げる。','関係部署と議論を重ね、実施計画をさらに練る必要がある。','관련 부서와 논의를 거듭해 실행 계획을 더 다듬을 필요가 있다.'),
('n1-1373','2026-11-12','憂鬱','ゆううつ','우울함; 마음이 무거움','心配・不安などで気分が沈み、晴れないさま。','雨の日が続くと、少し憂鬱な気分になることがある。','비 오는 날이 계속되면 조금 우울한 기분이 들 때가 있다.'),
('n1-1384','2026-11-12','明瞭','めいりょう','명료함; 분명함','内容・発音・区別などがはっきりしていて、分かりやすいさま。','説明は簡潔で明瞭だったため、参加者から質問はほとんど出なかった。','설명이 간결하고 명료해서 참가자들의 질문이 거의 나오지 않았다.'),
('n1-1342','2026-11-12','悟る','さとる','깨닫다; 알아차리다','物事の本質・真理・事情などを深く理解する。また、状況から何かを察知する。','説明を聞くうちに、自分の思い込みが原因だったと悟った。','설명을 듣는 동안 자신의 선입견이 원인이었다는 것을 깨달았다.'),
('n1-1349','2026-11-12','絶える','たえる','끊기다; 사라지다; 끝나다','続いていたものが途中でなくなり、それ以上続かなくなる。','この地域では長年受け継がれてきた伝統が絶えつつある。','이 지역에서는 오랫동안 이어진 전통이 끊길 위기에 있다.'),
('n1-1351','2026-11-12','取り戻す','とりもどす','되찾다; 회복하다','失った物・地位・信頼・健康・状態などを再び自分のもの、または元の状態に戻す。','品質改善を続け、少しずつ顧客の信頼を取り戻した。','품질 개선을 계속해 조금씩 고객의 신뢰를 되찾았다.'),
('n1-1370','2026-11-12','収まる','おさまる','가라앉다; 진정되다; 제자리에 들어가다','騒ぎ・怒り・勢いなどが静かになる。また、物が一定の場所や範囲の中に入る。','強い雨は一時間ほどで収まり、交通も徐々に回復した。','강한 비는 한 시간 정도 만에 잦아들었고 교통도 서서히 회복됐다.'),
('n1-1405','2026-11-12','引き取る','ひきとる','인수하다; 맡아 데려가다; 회수하다','人・物を自分の側で受け持つために受け取る。また、預けた物を受け取って持ち帰る。','修理が終わった機器を午後に店へ引き取りに行く。','수리가 끝난 기기를 오후에 가게로 찾으러 간다.'),
('n1-1426','2026-11-12','目覚める','めざめる','잠에서 깨다; 눈뜨다; 자각하다','眠りから覚める。また、今まで意識していなかった価値・思想・能力などに気づく。','海外生活をきっかけに、彼は異文化研究への関心に目覚めた。','해외 생활을 계기로 그는 이문화 연구에 대한 관심에 눈떴다.'),
('n1-1450','2026-11-12','立ち寄る','たちよる','들르다; 잠깐 방문하다','目的地へ行く途中などで、別の場所に短時間寄る。','帰宅する前にスーパーへ立ち寄って夕食の材料を買った。','귀가하기 전에 슈퍼에 들러 저녁 재료를 샀다.'),
('n1-1474','2026-11-12','乗り込む','のりこむ','올라타다; 들어가다; 현장에 직접 들어가다','乗り物の中へ入って乗る。また、勢いよく特定の場所へ入っていく。','調査チームは早朝に現地へ乗り込み、設備の確認を始めた。','조사팀은 이른 아침 현장에 들어가 설비 확인을 시작했다.'),
('n1-1502','2026-11-12','染める','そめる','물들이다; 염색하다','布・糸・髪などに色を付ける。また比喩的に、ある思想・雰囲気などの影響を強く与える。','職人は植物から取った染料で布を鮮やかな藍色に染めた。','장인은 식물에서 얻은 염료로 천을 선명한 남색으로 물들였다.'),
('n1-1541','2026-11-12','召す','めす','드시다; 입으시다 등(높임말)','『食べる・飲む・着る』などの尊敬語として用いられる語。多くは『お召しになる』『召し上がる』などの形で使う。','寒いので、もう一枚上着をお召しになった方がよいでしょう。','추우니 겉옷을 한 벌 더 입으시는 편이 좋겠습니다.'),
('n1-1552','2026-11-12','荒らす','あらす','어지럽히다; 훼손하다; 휩쓸다','場所・物を乱雑にしたり損なったりする。また、病気・犯罪などが広く被害を与える。','不法投棄によって山林が荒らされ、自治体が対策に乗り出した。','불법 투기로 산림이 훼손되어 지자체가 대책에 나섰다.'),
('n1-1562','2026-11-12','悩ます','なやます','괴롭히다; 고민하게 하다','心配・問題などによって、人を苦しませたり困らせたりする。','慢性的な人手不足が多くの中小企業を悩ませている。','만성적인 인력 부족이 많은 중소기업을 괴롭히고 있다.'),
('n1-1606','2026-11-12','読み上げる','よみあげる','소리 내어 읽다; 낭독하다','書かれた文章・数字・名前などを声に出して読む。','司会者が受賞者の名前を一人ずつ読み上げた。','사회자가 수상자 이름을 한 명씩 소리 내어 읽었다.'),
('n1-1392','2026-11-13','養う','やしなう','기르다; 부양하다; 함양하다','人・動物を生活できるよう世話して育てる。また、能力・習慣・感覚などを育て身につける。','多様な文章を読むことで、物事を批判的に考える力を養うことができる。','다양한 글을 읽음으로써 사물을 비판적으로 생각하는 힘을 기를 수 있다.'),
('n1-1407','2026-11-13','不吉','ふきつ','불길함; 좋지 않은 징조','悪い出来事が起こりそうで、縁起が悪いと感じられるさま。','その地方では、この鳥の鳴き声を不吉な兆しと考える言い伝えがある。','그 지방에는 이 새의 울음소리를 불길한 징조로 여기는 전승이 있다.'),
('n1-1420','2026-11-13','無口','むくち','말수가 적음; 과묵함','普段からあまり話さず、口数が少ないさま。','彼は無口だが、必要な時には的確な意見を述べる。','그는 말수가 적지만 필요할 때는 정확한 의견을 말한다.'),
('n1-1424','2026-11-13','望ましい','のぞましい','바람직하다; 이상적이다','そうなることが好ましく、理想的・適切だと思われる。','重要な変更は本番直前ではなく、十分な検証期間を取って行うのが望ましい。','중요한 변경은 운영 직전이 아니라 충분한 검증 기간을 확보해 실시하는 것이 바람직하다.'),
('n1-1427','2026-11-13','今更','いまさら','이제 와서; 새삼','すでに時期が遅い今になって。また、以前から分かっていたことを改めて感じるさま。','締切を過ぎてから今更条件を変えるのは難しい。','마감이 지난 뒤 이제 와서 조건을 바꾸기는 어렵다.'),
('n1-1431','2026-11-13','滑稽','こっけい','우스꽝스러움; 익살스러움','言動・状況などがおかしく、思わず笑いたくなるさま。','本人は真剣だったが、周囲から見ると少し滑稽な光景だった。','본인은 진지했지만 주변에서 보면 조금 우스꽝스러운 광경이었다.'),
('n1-1445','2026-11-13','到底','とうてい','도저히; 아무리 해도','どう考えても実現・理解・受容などができないことを強く表す副詞。多く否定表現とともに使う。','この人数では今日中に全件を確認するのは到底無理だ。','이 인원으로는 오늘 안에 전 건을 확인하는 것은 도저히 무리다.'),
('n1-1619','2026-11-13','苦しめる','くるしめる','괴롭히다; 고통을 주다','人に肉体的・精神的な苦痛を与える。また、問題などが人を悩ませる。','長引く物価上昇が家計を苦しめている。','장기화된 물가 상승이 가계를 괴롭히고 있다.'),
('n1-1621','2026-11-13','染まる','そまる','물들다; 영향을 받아 동화되다','色がつく。また比喩的に、思想・習慣・雰囲気などの影響を受け、その傾向を持つようになる。','夕日で空全体が赤く染まった。','석양으로 하늘 전체가 붉게 물들었다.'),
('n1-1624','2026-11-13','操る','あやつる','조종하다; 다루다; 마음대로 움직이다','機械・道具・言語などを巧みに扱う。また、人を意図どおりに動かす。','彼は三か国語を自在に操り、海外との交渉を担当している。','그는 세 나라 말을 자유자재로 구사하며 해외 협상을 담당하고 있다.'),
('n1-1633','2026-11-13','焦る','あせる','초조해하다; 조급해하다','思いどおりに進まないことなどで落ち着きを失い、急いで何とかしようとする。','時間が足りなくても焦らず、優先順位を決めて対応しよう。','시간이 부족해도 조급해하지 말고 우선순위를 정해 대응하자.'),
('n1-1644','2026-11-13','落ち込む','おちこむ','낙담하다; 침체되다; 움푹 들어가다','気分・成績・売上などが低下する。また、表面が周囲より低くへこむ。','失敗して落ち込んでいたが、原因を整理して次の対策を考えた。','실패해서 낙담했지만 원인을 정리해 다음 대책을 생각했다.'),
('n1-1645','2026-11-13','摘む','つまむ','집다; 꼬집듯 집어 올리다','指先で物の一部を挟んで持つ。','小さな部品は指でつままず、専用の工具で扱ってください。','작은 부품은 손가락으로 집지 말고 전용 공구로 다뤄 주세요.'),
('n1-1677','2026-11-13','呆れる','あきれる','기가 막히다; 어이없어하다; 질리다','あまりにひどい・意外なことに驚き、言葉を失うほどになる。','同じミスを何度も繰り返す態度には、さすがに呆れた。','같은 실수를 몇 번이나 반복하는 태도에는 정말 기가 막혔다.'),
('n1-1706','2026-11-13','寝かせる','ねかせる','눕히다; 재우다; 숙성시키다; 당분간 묵혀 두다','人を横にして眠らせる。また、物・計画などを一定期間そのまま置く。','この案はすぐ決めず、一晩寝かせてからもう一度検討しよう。','이 안은 바로 결정하지 말고 하룻밤 묵힌 뒤 다시 검토하자.'),
('n1-1792','2026-11-13','酷い','ひどい','심하다; 지독하다; 너무하다; 형편없다','程度が非常に激しい。また、状態・扱い・内容などが非常に悪い。','予想以上にひどい渋滞で、会場への到着が一時間以上遅れた。','예상보다 심한 정체 때문에 행사장 도착이 한 시간 넘게 늦어졌다.'),
('n1-1832','2026-11-13','説く','とく','설명하다; 설파하다; 주장하다','物事の道理・考えなどを説明し、相手に理解・納得させようとする。','教授は具体例を挙げながら、制度改革の必要性を説いた。','교수는 구체적인 예를 들면서 제도 개혁의 필요성을 설명하고 주장했다.'),
('n1-1902','2026-11-13','演じる','えんじる','연기하다; 역할을 맡다; 연기해 보이다','演劇・映画などで役を務め、その人物として表現する。また、人前で芸などを披露する。','彼は映画で複雑な過去を持つ刑事の役を見事に演じた。','그는 영화에서 복잡한 과거를 지닌 형사 역할을 훌륭하게 연기했다.'),
('n1-1932','2026-11-13','叶う','かなう','이루어지다; 실현되다','願い・希望などが実現して、望んでいたとおりになる。','長年の夢が叶い、ついに自分の店を開くことができた。','오랜 꿈이 이루어져 마침내 자신의 가게를 열 수 있었다.'),
('n1-1937','2026-11-13','名付ける','なづける','이름을 짓다; 명명하다; 이름 붙이다','人・物・事などに名前をつける。','両親は、生まれた子に願いを込めて名前を名付けた。','부모는 태어난 아이에게 소망을 담아 이름을 지었다.');
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1456','2026-11-14','滑らか','なめらか','매끄러움; 부드러움','表面に凹凸が少なくすべすべしているさま。また、動き・話し方・処理などが途切れず自然なさま。','処理速度を改善したことで、画面の動きが以前より滑らかになった。','처리 속도를 개선해 화면 움직임이 이전보다 부드러워졌다.'),
('n1-1460','2026-11-14','騙す','だます','속이다; 기만하다','嘘・偽りの説明などによって、相手に事実と違うことを信じ込ませる。','本物の銀行を装って利用者を騙す詐欺メールが増えている。','실제 은행을 사칭해 이용자를 속이는 사기 메일이 늘고 있다.'),
('n1-1464','2026-11-14','突如','とつじょ','돌연; 갑자기','予期しない出来事が、前触れなく急に起こるさま。','晴れていた空が突如暗くなり、激しい雨が降り始めた。','맑던 하늘이 돌연 어두워지며 강한 비가 내리기 시작했다.'),
('n1-1470','2026-11-14','頑丈','がんじょう','튼튼함; 견고함','物の作りが丈夫で壊れにくいさま。また、体が強く健康なさま。','屋外で使う装置なので、雨や衝撃に耐える頑丈なケースを選んだ。','야외에서 사용하는 장치라 비와 충격을 견디는 튼튼한 케이스를 골랐다.'),
('n1-1476','2026-11-14','円滑','えんかつ','원활함; 순조로움','物事が滞ったり対立したりせず、滑らかに進むさま。','部門間の情報共有を改善し、業務を円滑に進められるようにした。','부서 간 정보 공유를 개선해 업무를 원활하게 진행할 수 있도록 했다.'),
('n1-1484','2026-11-14','きっちり','きっちり','딱 맞게; 정확히; 빈틈없이','数量・時間・大きさなどがちょうど合うさま。また、仕事などを抜けなく正確に行うさま。','予定どおり九時きっちりに会議が始まった。','예정대로 정확히 9시에 회의가 시작됐다.'),
('n1-1487','2026-11-14','好ましい','このましい','바람직하다; 호감이 간다','良い・望ましいと感じられ、受け入れたいと思うさま。','利用者に誤解を与えないよう、より好ましい表現に修正した。','이용자에게 오해를 주지 않도록 더 바람직한 표현으로 수정했다.'),
('n1-1963','2026-11-14','相応しい','ふさわしい','알맞다; 적합하다; 어울리다','立場・条件・状況などによく合っている。','経験と実績を考えれば、彼はその役職にふさわしい。','경험과 실적을 생각하면 그는 그 직책에 적합하다.'),
('n1-1965','2026-11-14','組み込む','くみこむ','끼워 넣다; 포함시키다; 내장하다','あるものを全体の一部として中に入れる。','新しい認証機能を既存のシステムに組み込んだ。','새 인증 기능을 기존 시스템에 내장했다.'),
('n1-1969','2026-11-14','臨む','のぞむ','임하다; 직면하다; 마주하다','ある場面・仕事・状況に向き合う。また、場所が何かに面する。','十分に準備をして面接に臨んだ。','충분히 준비하고 면접에 임했다.'),
('n1-1973','2026-11-14','葬る','ほうむる','매장하다; 묻다; 묻어 버리다','死者を埋葬する。また、事実・計画などを表に出ないようにする。','その案は反対意見が多く、結局葬られた。','그 안은 반대 의견이 많아 결국 묻혀 버렸다.'),
('n1-1990','2026-11-14','盛り上がる','もりあがる','고조되다; 달아오르다; 부풀어 오르다','雰囲気・気運などが活発になる。また、形が高くふくらむ。','試合の終盤になると会場は一気に盛り上がった。','경기 막판이 되자 경기장 분위기가 단숨에 달아올랐다.'),
('n1-1995','2026-11-14','捧げる','ささげる','바치다; 헌신하다; 올리다','神・人などに物を差し出す。また、時間・人生などをある目的に尽くす。','彼は長年、研究に人生を捧げてきた。','그는 오랫동안 연구에 인생을 바쳐 왔다.'),
('n1-1998','2026-11-14','強まる','つよまる','강해지다; 거세지다','力・程度・勢いなどが強くなる。','台風が近づくにつれて風が強まってきた。','태풍이 가까워지면서 바람이 거세졌다.'),
('n1-1999','2026-11-14','差し出す','さしだす','내밀다; 제출하다; 내놓다','相手の方へ物を出す。また、書類などを提出する。','受付で身分証明書を差し出した。','접수처에서 신분증을 내밀었다.'),
('n1-2004','2026-11-14','退く','しりぞく','물러나다; 후퇴하다; 퇴임하다','後ろへ下がる。また、地位・役職などを離れる。','彼は責任を取って社長の座を退いた。','그는 책임을 지고 사장 자리에서 물러났다.'),
('n1-2013','2026-11-14','励む','はげむ','힘쓰다; 노력하다; 매진하다','目標に向かって一生懸命努力する。','資格取得を目指して毎日勉強に励んでいる。','자격증 취득을 목표로 매일 공부에 힘쓰고 있다.'),
('n1-2019','2026-11-14','浸す','ひたす','담그다; 적시다','液体の中に入れて十分にぬらす。','布を水に浸してから固く絞った。','천을 물에 적신 뒤 꽉 짰다.'),
('n1-2021','2026-11-14','惜しむ','おしむ','아끼다; 아까워하다; 애석해하다','大切にして無駄にしない。また、失うことを残念に思う。','彼は努力を惜しまず、最後まで練習を続けた。','그는 노력을 아끼지 않고 끝까지 연습을 계속했다.'),
('n1-2028','2026-11-14','舞う','まう','춤추다; 흩날리다; 빙빙 돌다','舞踊をする。また、花びら・雪などが空中をひらひら動く。','春風に乗って桜の花びらが舞っていた。','봄바람을 타고 벚꽃잎이 흩날리고 있었다.'),
('n1-1491','2026-11-15','頑固','がんこ','완고함; 고집이 셈','自分の考え・態度をなかなか変えず、人の意見を受け入れにくいさま。また、汚れなどが落ちにくいさま。','自分の方法に頑固にこだわるだけでは、状況の変化に対応できない。','자기 방식만 완고하게 고집해서는 상황 변화에 대응할 수 없다.'),
('n1-1495','2026-11-15','簡潔','かんけつ','간결함; 짧고 명확함','余分な内容がなく、短くまとまって分かりやすいさま。','障害報告は事実と原因を簡潔にまとめることが重要だ。','장애 보고는 사실과 원인을 간결하게 정리하는 것이 중요하다.'),
('n1-1497','2026-11-15','じっくり','じっくり','차분히; 충분히; 꼼꼼히','時間をかけて、落ち着いて十分に考えたり取り組んだりするさま。','転職先は条件だけで決めず、仕事内容も含めてじっくり考えたい。','이직할 곳은 조건만으로 정하지 않고 업무 내용까지 포함해 차분히 생각하고 싶다.'),
('n1-1500','2026-11-15','猛烈','もうれつ','맹렬함; 매우 격렬함','勢い・程度が非常に激しく、並外れて強いさま。','台風の接近に伴い、沿岸部では猛烈な風が吹いている。','태풍 접근에 따라 해안 지역에는 매우 거센 바람이 불고 있다.'),
('n1-1516','2026-11-15','過密','かみつ','과밀','人口・建物・予定などが一か所や一定期間に集中しすぎている状態。','都市部では人口の過密が交通や住宅の問題を深刻化させている。','도시 지역에서는 인구 과밀이 교통과 주택 문제를 심화시키고 있다.'),
('n1-1519','2026-11-15','損なう','そこなう','손상시키다; 해치다; 잃게 하다','価値・機能・健康・信頼・雰囲気などを悪くしたり失わせたりする。','説明不足は利用者の信頼を損なう原因になりかねない。','설명 부족은 이용자의 신뢰를 해칠 원인이 될 수 있다.'),
('n1-1524','2026-11-15','汚す','けがす','더럽히다; 훼손하다; 모독하다','名誉・神聖さ・純潔さなど、本来大切にすべき価値を傷つける。','事実ではない発言で故人の名誉を汚すべきではない。','사실이 아닌 발언으로 고인의 명예를 훼손해서는 안 된다.'),
('n1-2030','2026-11-15','据える','すえる','설치하다; 놓다; 앉히다; 정하다','物を一定の場所にしっかり置く。また、人を地位につけたり目標などを定めたりする。','部屋の中央に大きな机を据えた。','방 중앙에 큰 책상을 놓았다.'),
('n1-2032','2026-11-15','挑む','いどむ','도전하다; 맞서다','困難な課題・相手などに立ち向かう。','彼は世界記録の更新に挑んだ。','그는 세계 기록 경신에 도전했다.'),
('n1-2033','2026-11-15','唸る','うなる','신음하다; 으르렁거리다; 웅웅 소리나다','低く長い声・音を出す。動物がうなり声を上げたり、機械・風などが低く鳴ったりする。','強い風が窓の外で一晩中唸っていた。','강한 바람이 창밖에서 밤새 윙윙 울었다.'),
('n1-2042','2026-11-15','面する','めんする','면하다; 마주하다; 접하다','ある方向・場所に正面を向けて接している。','このホテルの部屋は海に面している。','이 호텔 객실은 바다를 향하고 있다.'),
('n1-2043','2026-11-15','慌てる','あわてる','당황하다; 허둥대다','急な出来事に驚き、落ち着きを失う。','財布が見つからなくても、まず慌てずに探そう。','지갑이 안 보여도 우선 당황하지 말고 찾아보자.'),
('n1-2044','2026-11-15','帯びる','おびる','띠다; 지니다; 맡다','ある性質・色・雰囲気などを含んで持つ。また、任務などを受け持つ。','空が少し赤みを帯びてきた。','하늘이 조금 붉은 기를 띠기 시작했다.'),
('n1-2059','2026-11-15','連ねる','つらねる','잇다; 나란히 늘어놓다; 이름을 올리다','物を一列につなげたり並べたりする。また、名を列に加える。','多くの著名人が賛同者として名を連ねた。','많은 유명 인사가 찬동자로 이름을 올렸다.'),
('n1-2061','2026-11-15','察する','さっする','헤아리다; 짐작하다; 알아차리다','事情・気持ちなどを推測して理解する。','彼の表情から事情を察した。','그의 표정에서 사정을 짐작했다.'),
('n1-2063','2026-11-15','交える','まじえる','섞다; 주고받다; 교차시키다','異なるものを一緒にする。また、言葉・意見などを互いにやり取りする。','冗談を交えながら説明した。','농담을 섞어 가며 설명했다.'),
('n1-2069','2026-11-15','申し出る','もうしでる','신청하다; 제의하다; 자청하다; 말하고 나서다','自分から希望・意見・提案などを相手に伝える。','彼は自分から作業を手伝うと申し出た。','그는 스스로 작업을 돕겠다고 나섰다.'),
('n1-2085','2026-11-15','漏れる','もれる','새다; 누설되다; 빠지다; 누락되다','液体・気体・光・音などが隙間から外へ出る。また、秘密が知られたり、必要なものが抜けたりする。','会議の内容が外部に漏れてしまった。','회의 내용이 외부에 새어 나가고 말았다.'),
('n1-2104','2026-11-15','励ます','はげます','격려하다; 북돋우다; 용기를 주다','相手が元気・勇気・意欲を持てるよう言葉などで力づける。','落ち込んでいる友人を励ました。','풀이 죽은 친구를 격려했다.'),
('n1-2116','2026-11-15','弱める','よわめる','약하게 하다; 약화시키다; 줄이다','力・程度・勢いなどを弱くする。','火が強すぎるので少し弱めてください。','불이 너무 세니 조금 약하게 해 주세요.');
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1537','2026-11-16','温和','おんわ','온화함; 온순함','性格・態度・気候などが穏やかで、激しさがないさま。','普段は温和な上司だが、安全に関する規則には厳しい。','평소에는 온화한 상사지만 안전 관련 규칙에는 엄격하다.'),
('n1-1544','2026-11-16','何しろ','なにしろ','어쨌든; 무엇보다; 워낙','事情・理由を強く説明するときに、『とにかく』『なんといっても』の意で用いる。','何しろ初めての海外勤務なので、準備することが多い。','워낙 첫 해외 근무라 준비할 것이 많다.'),
('n1-1545','2026-11-16','日夜','にちや','밤낮; 밤낮없이','昼も夜も。絶えず、毎日続けて。','研究チームは問題の解決に向けて日夜努力を続けている。','연구팀은 문제 해결을 위해 밤낮없이 노력을 계속하고 있다.'),
('n1-1547','2026-11-16','終日','しゅうじつ','종일; 하루 종일','朝から夜まで、一日じゅう。','台風の影響で空港は終日混雑していた。','태풍의 영향으로 공항은 하루 종일 혼잡했다.'),
('n1-1553','2026-11-16','丸々','まるまる','통째로; 전부; 꼬박','一部分も欠けず、全部そのまま。また、期間・数量が完全にその分だけあるさま。','引っ越しの準備には丸々一週間かかった。','이사 준비에는 꼬박 일주일이 걸렸다.'),
('n1-1556','2026-11-16','無茶苦茶','むちゃくちゃ','엉망진창; 터무니없음; 무리함','筋道・秩序がなく、ひどく乱れているさま。また、常識外れで無理なさま。','根拠のない数字を並べた無茶苦茶な計画では承認されない。','근거 없는 숫자를 늘어놓은 엉망인 계획으로는 승인받을 수 없다.'),
('n1-1559','2026-11-16','抜け出す','ぬけだす','빠져나오다; 벗어나다; 탈출하다','閉じた場所・集団・困難な状態などから外へ出る。','景気の停滞から抜け出すには、新しい需要を生み出す必要がある。','경기 침체에서 벗어나려면 새로운 수요를 만들어낼 필요가 있다.'),
('n1-2118','2026-11-16','付け加える','つけくわえる','덧붙이다; 추가하다; 부가하다','すでにあるものに、さらに説明・内容などを加える。','最後に一つだけ説明を付け加えた。','마지막으로 설명을 하나만 덧붙였다.'),
('n1-2127','2026-11-16','連なる','つらなる','이어지다; 줄지어 늘어서다; 연속되다','多くのものが一列に続く。また、つながって続く。','遠くまで山々が連なっている。','멀리까지 산들이 이어져 있다.'),
('n1-2139','2026-11-16','見逃す','みのがす','놓치다; 간과하다; 눈감아 주다','見るべきものを見落とす。また、過失などを知りながら問題にせず許す。','重要な変化を見逃してはいけない。','중요한 변화를 놓쳐서는 안 된다.'),
('n1-2146','2026-11-16','賑わう','にぎわう','붐비다; 번성하다; 활기를 띠다','人が多く集まり活気に満ちる。また、商売などが繁盛する。','週末の商店街は観光客で賑わっている。','주말 상점가는 관광객으로 붐빈다.'),
('n1-2160','2026-11-16','徹する','てっする','철저히 하다; 관철하다; 몰두하다','一つの方針・立場などを最後まで貫く。また、一つのことに徹底して打ち込む。','彼は最後まで聞き役に徹した。','그는 끝까지 듣는 역할에 철저히 임했다.'),
('n1-2166','2026-11-16','受け付ける','うけつける','접수하다; 받아들이다; 받다','申し込み・依頼・質問などを受け取って対応する。また、人や物事を受け入れる。','申請は今月末まで受け付けています。','신청은 이번 달 말까지 접수하고 있습니다.'),
('n1-2195','2026-11-16','駆ける','かける','달리다; 뛰어가다; 질주하다','速く走る。特に人や馬などが勢いよく走る。','馬が草原を勢いよく駆けていった。','말이 초원을 힘차게 달려갔다.'),
('n1-2196','2026-11-16','逞しい','たくましい','튼튼하다; 우람하다; 늠름하다','体・精神などが強く、力に満ちている。','子どもが以前より逞しく成長した。','아이가 전보다 튼튼하고 씩씩하게 자랐다.'),
('n1-2231','2026-11-16','備わる','そなわる','갖추어져 있다; 구비되다; 타고나다','必要な設備・能力・性質などがあらかじめ身についている。','この施設には最新の設備が備わっている。','이 시설에는 최신 설비가 갖춰져 있다.'),
('n1-2235','2026-11-16','沈める','しずめる','가라앉히다; 침수시키다','水面などにある物を水中へ沈ませる。','重りを付けて網を海中に沈めた。','추를 달아 그물을 바닷속에 가라앉혔다.'),
('n1-2244','2026-11-16','病む','やむ','병들다; 앓다; 마음을 앓다','病気になる、病気を患う。また、心を苦しめる状態にも使う。','彼は長い間、心を病んでいた。','그는 오랫동안 마음의 병을 앓고 있었다.'),
('n1-2251','2026-11-16','仕入れる','しいれる','매입하다; 사들이다; 물건을 떼오다','販売・使用するために商品・材料などを買い入れる。','店では毎朝市場から新鮮な魚を仕入れている。','가게에서는 매일 아침 시장에서 신선한 생선을 매입한다.'),
('n1-2260','2026-11-16','叶える','かなえる','이루어 주다; 소원을 실현시키다','願い・希望・要求などを実現させる。','いつか両親を海外旅行に連れて行くという夢を叶えたい。','언젠가 부모님을 해외여행에 모시고 가겠다는 꿈을 이루고 싶다.'),
('n1-1563','2026-11-17','渋い','しぶい','떫다; 탐탁지 않다; 차분하고 멋스럽다','柿などのように舌がしびれる味がする。また、表情・反応が不満そうであることや、派手でなく落ち着いた趣があることも表す。','予算案を示すと、部長は少し渋い顔をした。','예산안을 보여 주자 부장은 조금 탐탁지 않은 표정을 지었다.'),
('n1-1578','2026-11-17','恥じる','はじる','부끄러워하다; 수치스럽게 여기다','自分の行為・状態などを恥ずかしいと思う。','失敗そのものを恥じるより、そこから学ぶ姿勢が大切だ。','실패 자체를 부끄러워하기보다 거기서 배우는 자세가 중요하다.'),
('n1-1580','2026-11-17','悲惨','ひさん','비참함; 참혹함','目を背けたくなるほど痛ましく、みじめでひどいさま。','長引く内戦によって住民の生活は悲惨な状況に置かれた。','장기화된 내전으로 주민들의 생활은 비참한 상황에 놓였다.'),
('n1-1599','2026-11-17','一様','いちよう','한결같음; 동일함; 획일적임','全部が同じような状態・様子で、違いがほとんどないさま。','利用者の反応は一様ではなく、評価が大きく分かれた。','이용자 반응은 한결같지 않았고 평가가 크게 갈렸다.'),
('n1-1613','2026-11-17','露骨','ろこつ','노골적임; 숨김없음','考え・欲望・不快感などを隠さず、あまりにもはっきり表すさま。','特定の会社だけを優遇する露骨な対応には批判が集まった。','특정 회사만 우대하는 노골적인 대응에 비판이 모였다.'),
('n1-1617','2026-11-17','偏る','かたよる','치우치다; 편중되다','考え・数量・配置などが一方に寄り、均衡を欠く。','情報源が一つに偏ると、判断も偏りやすくなる。','정보원이 하나에 치우치면 판단도 편향되기 쉽다.'),
('n1-1629','2026-11-17','押し込む','おしこむ','밀어 넣다; 억지로 집어넣다','力を加えて物・人を狭い場所の中へ入れる。','荷物を無理に箱へ押し込むと、中の商品が壊れるおそれがある。','짐을 억지로 상자에 밀어 넣으면 안의 상품이 망가질 우려가 있다.'),
('n1-2273','2026-11-17','打ち切る','うちきる','중단하다; 끝내다; 종결하다','続いている仕事・交渉・放送などを途中で終わらせる。','両社は条件が合わず、交渉を打ち切った。','양사는 조건이 맞지 않아 협상을 중단했다.'),
('n1-2275','2026-11-17','重んじる','おもんじる','중시하다; 존중하다; 소중히 여기다','価値が高く重要なものとして大切に扱う。尊重する。','この会社は社員同士の信頼関係を重んじている。','이 회사는 직원 간의 신뢰 관계를 중시한다.'),
('n1-2283','2026-11-17','引っ掛ける','ひっかける','걸다; 걸치다; 걸려들게 하다; 속이다','物を何かに掛ける、衣服を軽く身に着ける。また、仕掛けなどで相手を捕らえたりだましたりする。','コートを椅子の背に引っ掛けて席に着いた。','코트를 의자 등받이에 걸쳐 놓고 자리에 앉았다.'),
('n1-2317','2026-11-17','安っぽい','やすっぽい','싸구려처럼 보이다; 값싸 보이다; 천박해 보이다','値段が安そうに見え、品質・品格が低く感じられる。','素材が薄いため、少し安っぽく見える。','소재가 얇아서 조금 싸구려처럼 보인다.'),
('n1-2319','2026-11-17','揺らぐ','ゆらぐ','흔들리다; 동요하다; 불안정해지다','物がゆらゆらと動く。また、信念・地位・状態などが不安定になる。','どんな批判を受けても、彼の決意は揺らがなかった。','어떤 비판을 받아도 그의 결심은 흔들리지 않았다.'),
('n1-2322','2026-11-17','裂ける','さける','찢어지다; 갈라지다; 터지다','一つにつながっていた物に切れ目が入り、二つ以上に分かれる。','古くなった袋が重さに耐えられず裂けてしまった。','낡은 봉지가 무게를 견디지 못하고 찢어졌다.'),
('n1-2330','2026-11-17','物足りない','ものたりない','아쉽다; 뭔가 부족하다; 만족스럽지 않다','何かが不足していて、十分に満足できない。','料理はおいしかったが、量が少なくて少し物足りなかった。','요리는 맛있었지만 양이 적어서 조금 아쉬웠다.'),
('n1-2339','2026-11-17','怯える','おびえる','겁먹다; 두려워하다; 무서워 떨다','恐怖を感じて怖がる。恐ろしさのために不安になる。','子どもは大きな雷の音に怯えていた。','아이는 큰 천둥소리에 겁먹고 있었다.'),
('n1-2352','2026-11-17','綴じる','とじる','철하다; 묶어 제본하다; 파일로 묶다','複数の紙などを糸・針金・金具などで一つにまとめる。','会議資料を順番に並べてファイルに綴じた。','회의 자료를 순서대로 정리해 파일에 철했다.'),
('n1-2364','2026-11-17','見落とす','みおとす','못 보고 지나치다; 간과하다','見るべきものに気付かず、見過ごす。','小さなミスを見落とさないよう、最後にもう一度確認した。','작은 실수를 놓치지 않도록 마지막에 다시 한번 확인했다.'),
('n1-2375','2026-11-17','食い違う','くいちがう','엇갈리다; 어긋나다; 서로 맞지 않다','意見・記憶・内容などが一致せず、ずれる。','二人の説明が大きく食い違っている。','두 사람의 설명이 크게 엇갈리고 있다.'),
('n1-2395','2026-11-17','冴える','さえる','맑아지다; 또렷하다; 솜씨가 빛나다','頭・感覚・音・色などがはっきり鮮明である。また、技量がよく発揮される。','今日は頭が冴えていて、仕事がよく進む。','오늘은 머리가 맑아서 일이 잘 진행된다.'),
('n1-2401','2026-11-17','荒っぽい','あらっぽい','거칠다; 난폭하다; 대충하다','言動・扱い方などが乱暴で細やかさに欠ける。','荷物をそんなに荒っぽく扱わないでください。','짐을 그렇게 거칠게 다루지 마세요.');
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1648','2026-11-18','快い','こころよい','기분 좋다; 상쾌하다','気分・感覚がよく、不快さがない。','窓を開けると快い風が入り、部屋の空気が一変した。','창문을 여니 기분 좋은 바람이 들어와 방의 공기가 확 바뀌었다.'),
('n1-1649','2026-11-18','尊い','たっとい','존귀하다; 매우 귀중하다','非常に価値が高く、敬うべきである。また、かけがえがなく貴重である。','災害現場で人命を守るために働く姿は尊い。','재난 현장에서 생명을 지키기 위해 일하는 모습은 존귀하다.'),
('n1-1652','2026-11-18','几帳面','きちょうめん','꼼꼼함; 빈틈없음','細かい点まできちんとし、物事を丁寧に処理するさま。','彼は几帳面な性格で、作業記録を毎日欠かさず残している。','그는 꼼꼼한 성격이라 작업 기록을 매일 빠짐없이 남긴다.'),
('n1-1653','2026-11-18','精密','せいみつ','정밀함; 정교함','細部まで正確で、非常に細かく作られているさま。','この装置は精密な測定が必要な研究で使用されている。','이 장치는 정밀한 측정이 필요한 연구에서 사용되고 있다.'),
('n1-1654','2026-11-18','陰気','いんき','음침함; 우울하고 어두운 분위기','雰囲気・性格などが暗く、晴れやかでないさま。','照明を変えたことで、陰気だった部屋の印象が明るくなった。','조명을 바꾸자 음침했던 방의 인상이 밝아졌다.'),
('n1-1656','2026-11-18','婉曲','えんきょく','완곡함; 에둘러 표현함','直接的な言い方を避け、角が立たないよう遠回しに表現すること。','相手を傷つけないよう、婉曲な表現で改善を求めた。','상대를 상처 입히지 않도록 완곡한 표현으로 개선을 요구했다.'),
('n1-1671','2026-11-18','ぶらぶら','ぶらぶら','어슬렁어슬렁; 빈둥빈둥; 흔들흔들','目的なく歩き回ったり、仕事をせず過ごしたりするさま。また、物が垂れて揺れるさま。','休日は予定を決めず、商店街をぶらぶら歩くことにした。','휴일에는 일정을 정하지 않고 상점가를 어슬렁어슬렁 걷기로 했다.'),
('n1-2402','2026-11-18','急かす','せかす','재촉하다; 서두르게 하다','早くするよう相手を何度も促す。','急かされると、かえってミスをしやすくなる。','재촉을 받으면 오히려 실수하기 쉬워진다.'),
('n1-2403','2026-11-18','書き取る','かきとる','받아 적다; 필기하다','聞いた言葉・文章などをそのまま書き記す。','先生が読み上げた文章を正確に書き取った。','선생님이 읽어 준 문장을 정확히 받아 적었다.'),
('n1-2405','2026-11-18','漏る','もる','새다; 누출되다','液体・気体・光などが隙間から外へ出る。','古い屋根から雨が漏っている。','낡은 지붕에서 비가 새고 있다.'),
('n1-2406','2026-11-18','萎む','しぼむ','시들다; 쪼그라들다; 오므라들다','膨らんでいたものが小さくなる。また、花などが張りを失ってしおれる。','時間がたつと風船が少しずつ萎んできた。','시간이 지나자 풍선이 조금씩 쪼그라들기 시작했다.'),
('n1-2408','2026-11-18','着飾る','きかざる','화려하게 차려입다; 멋지게 꾸며 입다','美しい服・装飾品などを身に着けて、華やかに装う。','参加者は皆、パーティーのために着飾っていた。','참가자들은 모두 파티를 위해 화려하게 차려입고 있었다.'),
('n1-2409','2026-11-18','弄る','いじる','만지작거리다; 손대다; 건드리다; 고치다','物に手を触れて動かしたり、少し変更したりする。','設定が分からないなら、むやみに機械を弄らないほうがいい。','설정을 모른다면 함부로 기계를 건드리지 않는 편이 좋다.'),
('n1-2411','2026-11-18','煙たい','けむたい','연기가 매캐하다; 어렵고 불편한 상대다','煙が目・鼻を刺激して苦しい。また、相手を気兼ねして近寄りにくい。','部屋の中が煙たくて、窓を開けた。','방 안이 연기로 매캐해서 창문을 열었다.'),
('n1-2413','2026-11-18','痺れる','しびれる','저리다; 마비되다; 감각이 둔해지다','体の一部の感覚が鈍くなり、びりびりする。また、強い感動に圧倒されることもある。','長時間正座していたので足が痺れた。','오랫동안 정좌하고 있어서 다리가 저렸다.'),
('n1-2416','2026-11-18','負かす','まかす','이기다; 패배시키다','勝負・競争などで相手を負けさせる。','決勝戦で強豪チームを負かした。','결승전에서 강팀을 이겼다.'),
('n1-2455','2026-11-18','捕らえる','とらえる','붙잡다; 포착하다; 사로잡다','逃げるものをつかまえる。また、物事・意味・特徴などをしっかりつかむ。','警察は逃げた容疑者をその日のうちに捕らえた。','경찰은 도망간 용의자를 그날 안에 붙잡았다.'),
('n1-2520','2026-11-18','途絶える','とだえる','끊기다; 두절되다; 중단되다','続いていたものが途中で切れて、続かなくなる。','大雪の影響で山村への交通が一時途絶えた。','폭설의 영향으로 산촌으로 가는 교통이 한때 두절되었다.'),
('n1-2535','2026-11-18','諄い','くどい','장황하다; 지겹도록 반복하다; 맛이 느끼하다','同じことを繰り返してしつこい。また、味や色などが濃すぎてしつこく感じられる。','説明が少しくどくて、要点が分かりにくかった。','설명이 조금 장황해서 요점을 이해하기 어려웠다.'),
('n1-2537','2026-11-18','代わる','かわる','대신하다; 교대하다; 대체되다','他の人・物の位置や役割を引き受ける。また、別のものに置き換わる。','担当者に代わって私が説明します。','담당자를 대신해 제가 설명하겠습니다.'),
('n1-1672','2026-11-19','売り出す','うりだす','판매를 시작하다; 내놓다; 널리 알리다','商品を新たに販売し始める。また、人・商品などを広く宣伝して世に出す。','メーカーは来月、新型端末を全国で売り出す予定だ。','제조사는 다음 달 신형 단말기를 전국에 판매하기 시작할 예정이다.'),
('n1-1673','2026-11-19','軽快','けいかい','경쾌함; 가볍고 산뜻함','動き・音・気分などが軽やかで、明るく心地よいさま。','軽快な音楽に合わせて参加者が歩き始めた。','경쾌한 음악에 맞춰 참가자들이 걷기 시작했다.'),
('n1-1676','2026-11-19','寛容','かんよう','관용; 너그러움','他人の違い・失敗などを広い心で受け入れ、厳しく責めないこと。','多様な価値観に寛容な組織ほど意見交換が活発になりやすい。','다양한 가치관에 관용적인 조직일수록 의견 교환이 활발해지기 쉽다.'),
('n1-1692','2026-11-19','不順','ふじゅん','불순; 고르지 못함; 순조롭지 않음','天候・体調・順序などが正常・一定でなく、順調でないこと。','天候不順が続き、野菜の出荷量が大きく減った。','고르지 못한 날씨가 이어져 채소 출하량이 크게 줄었다.'),
('n1-1693','2026-11-19','あやふや','あやふや','불분명함; 애매함; 흐지부지함','内容・態度・記憶などがはっきりせず、確かでないさま。','責任の範囲をあやふやにしたまま作業を始めるべきではない。','책임 범위를 애매하게 둔 채 작업을 시작해서는 안 된다.'),
('n1-1701','2026-11-19','貧弱','ひんじゃく','빈약함; 부실함','内容・設備・体格などが十分でなく、弱々しいさま。','根拠が貧弱なままでは、その提案を採用するのは難しい。','근거가 빈약한 채로는 그 제안을 채택하기 어렵다.'),
('n1-1707','2026-11-19','怒鳴る','どなる','고함치다; 호통치다','怒りなどから大きな声を出して相手を叱る。','部下を人前で怒鳴るような指導は適切ではない。','부하를 사람들 앞에서 호통치는 식의 지도는 적절하지 않다.'),
('n1-2548','2026-11-19','背く','そむく','거스르다; 어기다; 배반하다; 등지다','命令・約束・期待・道理などに反する。また、人や組織に背を向ける。','上司の命令に背いて独断で行動した。','상사의 명령을 어기고 독단적으로 행동했다.'),
('n1-2557','2026-11-19','頻りに','しきりに','자꾸; 빈번히; 연거푸; 열심히','同じことを何度も繰り返すさま。また、強く熱心に行うさま。','彼は時計をしきりに気にしていた。','그는 자꾸 시계를 신경 쓰고 있었다.'),
('n1-2558','2026-11-19','禁じる','きんじる','금하다; 금지하다','ある行為をしてはいけないと定める。','この区域では喫煙を禁じている。','이 구역에서는 흡연을 금지하고 있다.'),
('n1-2563','2026-11-19','強いる','しいる','강요하다; 억지로 시키다','相手の意思に反して、無理に何かをさせる。','社員に長時間労働を強いてはいけない。','직원에게 장시간 노동을 강요해서는 안 된다.'),
('n1-2565','2026-11-19','見掛ける','みかける','우연히 보다; 눈에 띄다','偶然その人・物を目にする。','駅で昔の同僚を見掛けた。','역에서 예전 동료를 우연히 봤다.'),
('n1-2571','2026-11-19','拘る','こだわる','집착하다; 고집하다; 세세하게 신경 쓰다','一つのことを強く気にし、特に重視する。','彼は素材の品質に強くこだわっている。','그는 소재의 품질을 매우 중요하게 생각한다.'),
('n1-2596','2026-11-19','転じる','てんじる','바뀌다; 전환하다; 방향을 바꾸다','方向・状態・話題などが別のものへ変わる、または変える。','話題を転じて、今後の計画について話した。','화제를 바꿔 앞으로의 계획에 대해 이야기했다.'),
('n1-2601','2026-11-19','賭ける','かける','걸다; 내기하다; 목숨 등을 걸다','勝負に金品などを出す。また、命・名誉などを危険にさらす覚悟をする。','彼は自分の名誉を賭けて真相を明らかにした。','그는 자신의 명예를 걸고 진상을 밝혔다.'),
('n1-2604','2026-11-19','申し入れる','もうしいれる','제안하다; 요청하다; 신청하다','相手に意見・希望・要求などを正式に伝える。','労働組合は会社側に待遇改善を申し入れた。','노동조합은 회사 측에 처우 개선을 요청했다.'),
('n1-2605','2026-11-19','引きずる','ひきずる','질질 끌다; 계속 영향을 받다; 오래 끌다','物を地面などにつけたまま引く。また、過去の出来事・感情などの影響を長く残す。','失敗をいつまでも引きずらないほうがいい。','실패를 언제까지나 끌고 가지 않는 편이 좋다.'),
('n1-2614','2026-11-19','跨ぐ','またぐ','가랑이를 벌려 넘다; 걸터앉다; 걸치다','足を左右に開いて物の上を越える、またはまたがって乗る。','道路の溝を跨いで反対側へ渡った。','도로의 도랑을 성큼 넘어 반대편으로 갔다.'),
('n1-2627','2026-11-19','漕ぐ','こぐ','노를 젓다; 페달을 밟다; 그네를 구르다','櫓・オールを動かして船を進める。また、自転車のペダルやブランコを動かす。','二人でボートを漕いで湖を渡った。','둘이서 보트의 노를 저어 호수를 건넜다.'),
('n1-2633','2026-11-19','掬う','すくう','뜨다; 퍼내다; 건져 올리다','水・粉などを手や道具で下から受けて取り上げる。','両手で水を掬って顔を洗った。','두 손으로 물을 떠서 얼굴을 씻었다.');
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1709','2026-11-20','代わる代わる','かわるがわる','번갈아; 교대로','複数の人が順番を替えながら、同じ行動をするさま。','家族が代わる代わる病院へ見舞いに訪れた。','가족들이 번갈아 병문안을 갔다.'),
('n1-1710','2026-11-20','くっきり','くっきり','선명하게; 또렷하게','形・色・境界・記憶などが明確ではっきりしているさま。','雨上がりの空に山の稜線がくっきり見えた。','비가 그친 하늘에 산 능선이 선명하게 보였다.'),
('n1-1713','2026-11-20','心強い','こころづよい','든든하다; 믿음직하다','頼りになる人・材料などがあり、不安が少なく安心できる。','経験豊富な先輩が同じチームにいるのは心強い。','경험 많은 선배가 같은 팀에 있는 것은 든든하다.'),
('n1-1721','2026-11-20','殊に','ことに','특히; 유난히','ほかと比べて特に。とりわけ。','今年の夏は暑かったが、八月後半は殊に厳しい暑さが続いた。','올여름은 더웠지만 8월 후반은 특히 심한 더위가 계속됐다.'),
('n1-1822','2026-11-20','少なくとも','すくなくとも','적어도; 최소한','最低限その程度・数量には達している、またはその条件だけは満たすという意味を表す。','結論を出す前に、少なくとも関係者全員の意見は確認すべきだ。','결론을 내리기 전에 적어도 관계자 전원의 의견은 확인해야 한다.'),
('n1-1841','2026-11-20','どうやら','どうやら','아무래도; 보아하니; 어떻게든','はっきりとは分からないが、状況からそうらしいと推測するさま。また、何とかという意味にも用いる。','ログを確認したところ、どうやら設定変更が障害の原因らしい。','로그를 확인해 보니 아무래도 설정 변경이 장애의 원인인 듯하다.'),
('n1-1855','2026-11-20','何より','なにより','무엇보다; 무엇보다도; 가장','ほかのどんなことよりも重要・優先であることを表す。','予定どおり終えることも大切だが、安全を確保することが何より重要だ。','예정대로 끝내는 것도 중요하지만 안전을 확보하는 것이 무엇보다 중요하다.'),
('n1-2635','2026-11-20','研ぐ','とぐ','갈다; 연마하다; 쌀을 씻다','刃物などをこすって鋭くする。また、米を水で洗う。','料理の前に包丁を研いだ。','요리 전에 식칼을 갈았다.'),
('n1-2636','2026-11-20','弱まる','よわまる','약해지다; 누그러지다; 감소하다','力・勢い・程度などが弱くなる。','夕方になると雨の勢いが弱まった。','저녁이 되자 비의 기세가 약해졌다.'),
('n1-2646','2026-11-20','剥がす','はがす','떼다; 벗기다; 뜯어내다','付着している物を表面から取り離す。','箱に貼ってある古いシールを剥がした。','상자에 붙어 있는 오래된 스티커를 떼었다.'),
('n1-2649','2026-11-20','危ぶむ','あやぶむ','위태롭게 여기다; 우려하다; 의심하다','うまくいくか、安全かなどについて不安・疑いを持つ。','専門家は計画の実現性を危ぶんでいる。','전문가들은 계획의 실현 가능성을 우려하고 있다.'),
('n1-2651','2026-11-20','取り次ぐ','とりつぐ','전달하다; 중개하다; 전화를 연결하다','人と人の間に入って、用件・電話などを相手へ伝える。','担当者に電話を取り次いでもらった。','담당자에게 전화를 연결해 달라고 했다.'),
('n1-2652','2026-11-20','遅らす','おくらす','늦추다; 지연시키다','予定・時刻・進行などを後へずらす。','悪天候のため出発を一時間遅らした。','악천후 때문에 출발을 한 시간 늦췄다.'),
('n1-2654','2026-11-20','聳える','そびえる','우뚝 솟다; 높이 치솟다','山・建物などが非常に高く立つ。','街の中心に高層ビルが聳えている。','도시 중심에 고층 빌딩이 우뚝 솟아 있다.'),
('n1-2658','2026-11-20','染みる','しみる','스며들다; 배다; 사무치다; 따갑게 느껴지다','液体・色・味などが内部に入り込む。また、刺激や感情などが深く感じられる。','冷たい風が傷口に染みて痛い。','차가운 바람이 상처에 스며들어 따갑다.'),
('n1-2662','2026-11-20','下らない','くだらない','시시하다; 하찮다; 가치 없다','価値・意味・面白みがなく、取るに足りない。','くだらないことで言い争うのはやめよう。','시시한 일로 말다툼하는 건 그만하자.'),
('n1-2663','2026-11-20','心掛ける','こころがける','유념하다; 늘 ~하려고 하다','あることを常に意識し、そうするよう努める。','毎日少しでも運動するよう心掛けている。','매일 조금이라도 운동하려고 늘 유념하고 있다.'),
('n1-2665','2026-11-20','改まる','あらたまる','바뀌다; 개선되다; 격식을 차리다','状態が新しくなる、正される。また、態度や場が正式で堅いものになる。','急に改まった口調になったので少し驚いた。','갑자기 격식을 차린 말투가 되어 조금 놀랐다.'),
('n1-2666','2026-11-20','欺く','あざむく','속이다; 기만하다','嘘や策略によって相手を誤って信じさせる。','巧みな話術で人を欺いて金を取った。','교묘한 말솜씨로 사람을 속여 돈을 빼앗았다.'),
('n1-2667','2026-11-20','老いる','おいる','늙다; 나이가 들다','年齢を重ねて老年になる。','人は誰でも少しずつ老いていく。','사람은 누구나 조금씩 나이가 들어 간다.'),
('n1-1856','2026-11-21','生まれつき','うまれつき','타고나기를; 선천적으로; 천성적으로','生まれたときから備わっている性質・特徴であること。','彼女は生まれつき耳がよく、小さな音の違いにもすぐ気づく。','그녀는 타고나기를 귀가 밝아서 작은 소리의 차이도 바로 알아챈다.'),
('n1-1868','2026-11-21','恐らく','おそらく','아마; 아마도','確実ではないが、そうなる可能性が高いと推測するさま。','現在の進捗を見る限り、作業の完了は恐らく来週になるだろう。','현재 진척을 보면 작업 완료는 아마 다음 주가 될 것이다.'),
('n1-1883','2026-11-21','相変わらず','あいかわらず','여전히; 변함없이; 예전과 마찬가지로','以前と変わらず、同じ状態が続いているさま。','数年ぶりに会ったが、彼は相変わらず忙しそうに働いていた。','몇 년 만에 만났지만 그는 여전히 바쁘게 일하고 있는 듯했다.'),
('n1-1947','2026-11-21','組み合わせる','くみあわせる','조합하다; 짜 맞추다; 결합하다','複数のものを取り合わせて一つのまとまりにする。','異なる色の素材をうまく組み合わせると、印象的なデザインになる。','서로 다른 색의 소재를 잘 조합하면 인상적인 디자인이 된다.'),
('n1-1952','2026-11-21','親しむ','したしむ','친숙해지다; 가까이하다; 즐겨 접하다','人と親しく付き合う。また、物事を身近に感じ、好んで接したり楽しんだりする。','子どものころから本に親しむ習慣を身につけることは大切だ。','어릴 때부터 책을 가까이하는 습관을 들이는 것은 중요하다.'),
('n1-1991','2026-11-21','嘆く','なげく','한탄하다; 슬퍼하다','悲しみ・残念さなどを強く感じてため息をついたり訴えたりする。','失敗を嘆くだけでなく、原因を考えることが大切だ。','실패를 한탄하기보다 원인을 생각하는 것이 중요하다.'),
('n1-2031','2026-11-21','辛うじて','かろうじて','간신히; 가까스로','困難な状況で、ぎりぎり何とか実現するさま。','終電に辛うじて間に合った。','막차에 가까스로 맞췄다.'),
('n1-2668','2026-11-21','洒落る','しゃれる','멋을 내다; 세련되게 꾸미다; 재치 있는 말을 하다','服装などをしゃれて整える。また、しゃれを言う。','今日は少し洒落れた服を着て出かけた。','오늘은 조금 멋을 낸 옷을 입고 나갔다.'),
('n1-2677','2026-11-21','似通う','にかよう','매우 닮다; 유사하다','性質・形などが互いによく似ている。','二つの案は内容がかなり似通っている。','두 안은 내용이 상당히 비슷하다.'),
('n1-2680','2026-11-21','剥ぐ','はぐ','벗기다; 떼어 내다; 가죽을 벗기다','皮・衣服などを取り去る。','木の表面から古い樹皮を剥いだ。','나무 표면에서 낡은 껍질을 벗겨 냈다.'),
('n1-2682','2026-11-21','寄越す','よこす','보내다; 넘겨주다; 이쪽으로 보내오다','物・人・連絡などを自分のいる側へ送る。','必要な資料を今日中にこちらへ寄越してください。','필요한 자료를 오늘 안에 이쪽으로 보내 주세요.'),
('n1-2687','2026-11-21','強請る','ねだる','조르다; 졸라 요구하다','相手に物や行為をしつこく求める。','子どもがお菓子を買ってほしいと母親にねだった。','아이가 과자를 사 달라고 엄마에게 졸랐다.'),
('n1-2690','2026-11-21','揉める','もめる','분쟁이 생기다; 다투다; 갈등하다','意見や利害が合わず、争い・ごたごたが起こる。','契約条件をめぐって両社が揉めている。','계약 조건을 둘러싸고 양사가 갈등하고 있다.'),
('n1-2692','2026-11-21','恵む','めぐむ','베풀다; 은혜를 주다; 적선하다','困っている人などに金品や恩恵を与える。','彼は貧しい人々に食べ物を恵んだ。','그는 가난한 사람들에게 음식을 베풀었다.'),
('n1-2699','2026-11-21','ぶら下げる','ぶらさげる','매달다; 늘어뜨리다; 달랑거리게 하다','物を下に垂れ下がるように掛ける。','かばんを肩からぶら下げて歩いた。','가방을 어깨에 매달고 걸었다.'),
('n1-2700','2026-11-21','呟く','つぶやく','중얼거리다; 혼잣말하다','小さな声で独り言のように言う。','彼は結果を見て『信じられない』と呟いた。','그는 결과를 보고 ''믿을 수 없다''고 중얼거렸다.'),
('n1-2703','2026-11-21','凭れる','もたれる','기대다; 위에 기대어 의지하다; 속이 더부룩하다','物に体を預けて寄りかかる。また、食べ物で胃が重く感じられる。','疲れたので壁に凭れて休んだ。','피곤해서 벽에 기대어 쉬었다.'),
('n1-2704','2026-11-21','腫れる','はれる','붓다; 부어오르다','炎症・けがなどで体の一部がふくらむ。','虫に刺されて腕が腫れた。','벌레에 물려 팔이 부었다.'),
('n1-2707','2026-11-21','備え付ける','そなえつける','비치하다; 설치하다; 갖추어 두다','必要な設備・器具などをあらかじめ設置しておく。','各部屋に消火器を備え付けている。','각 방에 소화기를 비치해 두고 있다.'),
('n1-2708','2026-11-21','治まる','おさまる','가라앉다; 진정되다; 수습되다','痛み・怒り・混乱などが静まり、落ち着いた状態になる。','薬を飲んだら頭痛が少し治まった。','약을 먹었더니 두통이 조금 가라앉았다.');
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2034','2026-11-22','受け止める','うけとめる','받아내다; 받아들이다; 이해하다','向かってくるものを受ける。また、意見・事実などを理解し受け入れる。','批判を感情的にならずに受け止める必要がある。','비판을 감정적으로 반응하지 않고 받아들일 필요가 있다.'),
('n1-2035','2026-11-22','持てる','もてる','인기가 있다; 호감을 받다','異性などから人気があり、好かれる。','彼は話が面白くて昔からよく持てる。','그는 말이 재미있어서 예전부터 인기가 많다.'),
('n1-2053','2026-11-22','衰える','おとろえる','쇠하다; 약해지다; 쇠퇴하다','力・能力・勢いなどが以前より弱くなる。','運動をやめると体力は少しずつ衰える。','운동을 그만두면 체력은 조금씩 약해진다.'),
('n1-2068','2026-11-22','微か','かすか','희미함; 어렴풋함; 미약함','音・光・記憶などが弱く、はっきりしないさま。','遠くから微かな声が聞こえた。','멀리서 희미한 목소리가 들렸다.'),
('n1-2073','2026-11-22','粋','いき','멋스러움; 세련됨; 멋진','服装・振る舞いなどが洗練され、しゃれているさま。','彼は粋な着物の着こなしをしている。','그는 세련되게 기모노를 입고 있다.'),
('n1-2080','2026-11-22','凌ぐ','しのぐ','능가하다; 견디다; 넘기다','他より優れる。また、困難・暑さ・寒さなどを耐えて切り抜ける。','今年の売上は昨年を凌ぐ勢いだ。','올해 매출은 작년을 능가할 기세다.'),
('n1-2087','2026-11-22','漠然','ばくぜん','막연함; 모호함','内容・範囲などがはっきりせず、ぼんやりしているさま。','将来について漠然とした不安を感じている。','장래에 대해 막연한 불안을 느끼고 있다.'),
('n1-2711','2026-11-22','煙る','けむる','연기가 나다; 연기로 흐려지다','煙が立つ。また、煙や霧などでぼんやりかすむ。','焚き火の煙で周囲が煙っていた。','모닥불 연기 때문에 주변이 뿌옇게 흐려져 있었다.'),
('n1-2721','2026-11-22','霞む','かすむ','희미해지다; 뿌옇게 보이다; 흐려지다','霞などで物がぼんやり見える。また、目がかすんで見えにくくなる。','遠くの山が霞んで見える。','멀리 있는 산이 희미하게 보인다.'),
('n1-2723','2026-11-22','澄ます','すます','맑게 하다; 태연한 척하다; 새침한 표정을 짓다','濁りをなくして澄んだ状態にする。また、何事もないような顔をする。','彼は何も知らないような顔を澄ましていた。','그는 아무것도 모르는 듯 태연한 표정을 짓고 있었다.'),
('n1-2728','2026-11-22','拵える','こしらえる','만들다; 마련하다; 꾸리다','物を作る。また、金・仕事・荷物などを用意する。','旅行のために弁当を拵えた。','여행을 위해 도시락을 만들었다.'),
('n1-2729','2026-11-22','滲む','にじむ','번지다; 배어 나오다; 스미다; 어리다','液体・色などが広がる。また、感情などが表面に現れる。','涙が目に滲んだ。','눈물이 눈에 어렸다.'),
('n1-2734','2026-11-22','潤う','うるおう','촉촉해지다; 풍요로워지다; 혜택을 보다','水分を得て湿る。また、利益・恩恵を受けて豊かになる。','観光客が増えて地域経済が潤った。','관광객이 늘어 지역 경제가 활기를 얻었다.'),
('n1-2735','2026-11-22','待ち望む','まちのぞむ','손꼽아 기다리다; 고대하다','実現や到来を強く期待して待つ。','多くの人が新サービスの開始を待ち望んでいる。','많은 사람이 새 서비스 시작을 손꼽아 기다리고 있다.'),
('n1-2737','2026-11-22','見合わせる','みあわせる','보류하다; 연기하다; 서로 바라보다','実施を一時控える。また、互いに顔を見合う。','悪天候のためイベントの開催を見合わせた。','악천후 때문에 행사 개최를 보류했다.'),
('n1-2103','2026-11-22','害する','がいする','해치다; 손상시키다; 방해하다','健康・利益・状態などに悪い影響や損害を与える。','睡眠不足は健康を害するおそれがある。','수면 부족은 건강을 해칠 우려가 있다.'),
('n1-2124','2026-11-22','化ける','ばける','둔갑하다; 변신하다; 전혀 다른 모습이 되다','別の姿・性質のものに変わる。特に妖怪などが姿を変える。','昔話では狐が人間に化けることがある。','옛이야기에서는 여우가 사람으로 둔갑하기도 한다.'),
('n1-2135','2026-11-22','鈍感','どんかん','둔감함; 눈치가 둔함','感覚・感情・周囲の変化などを感じ取る力が鈍いこと。','彼は周囲の視線にかなり鈍感だ。','그는 주변의 시선에 상당히 둔감하다.'),
('n1-2142','2026-11-22','前もって','まえもって','미리; 사전에','あることが起こる前にあらかじめ。','参加できない場合は前もって連絡してください。','참가할 수 없는 경우에는 미리 연락해 주세요.'),
('n1-2147','2026-11-22','苛々','いらいら','초조함; 짜증; 안절부절못함','思いどおりにならず、落ち着かず腹立たしい気持ちになること。','電車がなかなか来なくて苛々した。','전철이 좀처럼 오지 않아 짜증이 났다.'),
('n1-2149','2026-11-23','取り巻く','とりまく','둘러싸다; 에워싸다; 주변을 둘러싼','あるものの周囲を囲む。また、その周辺に存在して影響を与える。','企業を取り巻く環境は大きく変化している。','기업을 둘러싼 환경은 크게 변화하고 있다.'),
('n1-2164','2026-11-23','善良','ぜんりょう','선량함; 착함','性質・行いが正しく、素直でよいこと。','彼は善良で誠実な人として知られている。','그는 선량하고 성실한 사람으로 알려져 있다.'),
('n1-2175','2026-11-23','脱する','だっする','벗어나다; 탈피하다','困難・危険・悪い状態などから抜け出す。','長い不況をようやく脱する兆しが見えてきた。','긴 불황에서 마침내 벗어날 조짐이 보이기 시작했다.'),
('n1-2181','2026-11-23','清らか','きよらか','맑고 깨끗함; 순수함','汚れがなく清潔・純粋で美しいさま。','山から清らかな水が流れている。','산에서 맑고 깨끗한 물이 흐르고 있다.'),
('n1-2185','2026-11-23','喧しい','やかましい','시끄럽다; 까다롭다; 엄격하다','音がうるさい。また、細かいことに厳しい・口うるさい。','隣の工事の音が朝から喧しい。','옆 공사 소리가 아침부터 시끄럽다.'),
('n1-2210','2026-11-23','至って','いたって','지극히; 매우; 아주','非常に。きわめて。','本人は至って元気そうだった。','본인은 매우 건강해 보였다.'),
('n1-2212','2026-11-23','丸ごと','まるごと','통째로; 전부','分けたり除いたりせず、全部そのまま。','りんごを皮ごと丸ごと食べた。','사과를 껍질째 통째로 먹었다.'),
('n1-2215','2026-11-23','尊ぶ','たっとぶ','존중하다; 귀하게 여기다','価値あるものとして大切にし、敬う。','この地域では昔から自然を尊ぶ文化がある。','이 지역에는 예부터 자연을 존중하는 문화가 있다.'),
('n1-2232','2026-11-23','月並み','つきなみ','평범함; 진부함; 매달 정례','ありふれていて平凡なさま。また、本来は毎月・月ごとの意味。','月並みな表現だが、健康が一番大切だ。','진부한 표현이지만 건강이 가장 중요하다.'),
('n1-2234','2026-11-23','がっくり','がっくり','풀이 죽어; 크게 실망하여; 푹','強く落胆するさま。また、力が抜けて頭や体を落とすさま。','試験に落ちたと知って、彼はがっくり肩を落とした。','시험에 떨어졌다는 것을 알고 그는 크게 낙담했다.'),
('n1-2236','2026-11-23','咎める','とがめる','나무라다; 책망하다; 문제 삼다','過ち・失敗などを責める。また、傷などの状態が悪くなる意味もある。','小さな失敗を必要以上に咎めるべきではない。','작은 실수를 필요 이상으로 나무라서는 안 된다.'),
('n1-2249','2026-11-23','乱す','みだす','흐트러뜨리다; 어지럽히다; 혼란시키다','整っている状態・秩序・心などを乱れた状態にする。','私語は会議の秩序を乱す原因になる。','사적인 대화는 회의 질서를 어지럽히는 원인이 된다.'),
('n1-2253','2026-11-23','健やか','すこやか','건강함; 튼튼함; 건전함','心身が健康で、元気に成長・生活しているさま。','子どもが健やかに育つことを願っている。','아이가 건강하게 자라기를 바라고 있다.'),
('n1-2254','2026-11-23','交わる','まじわる','교차하다; 어울리다; 교류하다','線などが交差する。また、人と付き合い、交流する。','二本の道路がこの地点で交わる。','두 도로가 이 지점에서 교차한다.'),
('n1-2262','2026-11-23','きっぱり','きっぱり','단호하게; 딱 잘라; 명확하게','態度・発言などを迷いなく、はっきりと示すさま。','彼は無理な依頼をきっぱり断った。','그는 무리한 부탁을 단호하게 거절했다.'),
('n1-2266','2026-11-23','切ない','せつない','애달프다; 애틋하다; 가슴이 아프다','悲しさ・寂しさなどで胸が締め付けられるようにつらい。','別れの場面を見ると、切ない気持ちになる。','이별 장면을 보면 애달픈 마음이 든다.'),
('n1-2271','2026-11-23','過多','かた','과다; 지나치게 많음','数量・程度などが必要以上に多いこと。','情報過多になると、かえって判断が難しくなることがある。','정보가 과다하면 오히려 판단하기 어려워질 수 있다.'),
('n1-2282','2026-11-23','惨め','みじめ','비참함; 초라함; 처참함','見ていられないほどかわいそうで、情けない状態。','準備不足で何も答えられず、惨めな気持ちになった。','준비 부족으로 아무것도 대답하지 못해 비참한 기분이 들었다.'),
('n1-2286','2026-11-23','明朗','めいろう','명랑함; 밝고 쾌활함; 명확함','性格・雰囲気などが明るく朗らかなこと。また、内容が明確で分かりやすいこと。','彼女は明朗な性格で、いつも周囲を明るくする。','그녀는 명랑한 성격으로 늘 주변 분위기를 밝게 만든다.'),
('n1-2293','2026-11-23','長閑','のどか','한가롭다; 평온하다; 여유롭다','静かで穏やかで、のんびりしているさま。','春の田舎には長閑な風景が広がっていた。','봄의 시골에는 한가롭고 평온한 풍경이 펼쳐져 있었다.');
INSERT INTO _n1_b4_words_0103(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2296','2026-11-24','冷酷','れいこく','냉혹함; 인정사정없음; 매정함','思いやりや情けがなく、非常に冷たいこと。','彼は利益のためなら人を切り捨てる冷酷な人物として描かれている。','그는 이익을 위해서라면 사람을 버리는 냉혹한 인물로 그려진다.'),
('n1-2298','2026-11-24','妬む','ねたむ','질투하다; 시샘하다; 부러워하며 미워하다','他人の成功・能力・幸福などをうらやみ、憎らしく思う。','他人の成功を妬むより、自分の目標に集中したほうがいい。','다른 사람의 성공을 질투하기보다 자신의 목표에 집중하는 편이 좋다.'),
('n1-2304','2026-11-24','容易い','たやすい','쉽다; 용이하다; 손쉽다','難しくなく、簡単にできる。','長年の問題を解決するのは、決して容易いことではない。','오랜 문제를 해결하는 것은 결코 쉬운 일이 아니다.'),
('n1-2305','2026-11-24','軒並み','のきなみ','집들이 줄지어 있음; 하나같이; 모조리','家が軒を並べて続いていること。また、複数のものが例外なく同じような状態になるさま。','原材料費の上昇で、各社の商品価格が軒並み上がった。','원재료비 상승으로 각 회사의 상품 가격이 하나같이 올랐다.'),
('n1-2307','2026-11-24','差し掛かる','さしかかる','접어들다; 다다르다; 가까워지다','ある場所に近づく。また、ある時期・段階に入ろうとする。','夕方に差し掛かるころ、急に雨が降り始めた。','저녁 무렵에 접어들 즈음 갑자기 비가 내리기 시작했다.'),
('n1-2310','2026-11-24','和らげる','やわらげる','누그러뜨리다; 완화하다; 덜어 주다','強さ・苦痛・緊張・怒りなどを弱くし、穏やかにする。','この薬には痛みを和らげる効果がある。','이 약에는 통증을 완화하는 효과가 있다.'),
('n1-2312','2026-11-24','強いて','しいて','굳이; 억지로; 강제로','無理を押して行うさま。また、あえて一つを選ぶなら、という意味で使う。','強いて一つ選ぶなら、この案が最も現実的だ。','굳이 하나를 고르자면 이 안이 가장 현실적이다.'),
('n1-2318','2026-11-24','何卒','なにとぞ','아무쪼록; 부디; 제발','相手に強く願い頼む気持ちを丁寧に表す語。どうか。','今後とも何卒よろしくお願い申し上げます。','앞으로도 아무쪼록 잘 부탁드립니다.'),
('n1-2327','2026-11-24','差し支える','さしつかえる','지장을 주다; 방해가 되다; 곤란을 초래하다','仕事・行動などを進めるうえで支障になる。','業務に差し支えるほどの体調不良なら、無理せず休んでください。','업무에 지장이 생길 정도로 몸이 좋지 않다면 무리하지 말고 쉬세요.'),
('n1-2331','2026-11-24','未練','みれん','미련; 아쉬움; 마음을 떨치지 못함','諦めるべきことへの思いを断ち切れず、心が残っていること。','前の仕事に未練はなく、新しい環境で頑張りたい。','이전 일에 미련은 없고 새로운 환경에서 열심히 하고 싶다.'),
('n1-2334','2026-11-24','ずるずる','ずるずる','질질; 계속 미루며; 흐지부지 계속','物を引きずるさま。また、好ましくない状態をはっきり終わらせず長引かせるさま。','結論を出さないまま、話し合いをずるずる続けるべきではない。','결론을 내리지 않은 채 논의를 질질 끌어서는 안 된다.'),
('n1-2341','2026-11-24','夥しい','おびただしい','엄청나게 많다; 수없이 많다; 막대하다','数量・程度が非常に多い、または甚だしい。','災害現場には夥しい量の土砂が流れ込んでいた。','재해 현장에는 엄청난 양의 토사가 밀려들어 와 있었다.'),
('n1-2342','2026-11-24','和やか','なごやか','화기애애하다; 온화하다; 부드럽고 평온하다','雰囲気・表情などが穏やかで、打ち解けているさま。','会食は終始和やかな雰囲気で進んだ。','회식은 처음부터 끝까지 화기애애한 분위기로 진행됐다.'),
('n1-2349','2026-11-24','卑しい','いやしい','천하다; 상스럽다; 비열하다; 탐욕스럽다','品性・言動などが下品で、品位に欠ける。また、欲深く浅ましい。','人の弱みにつけ込むような卑しい行為はやめるべきだ。','남의 약점을 이용하는 비열한 행동은 그만두어야 한다.'),
('n1-2358','2026-11-24','精巧','せいこう','정교함; 매우 섬세하고 치밀함','細部までよく作られていて、非常に巧みで精密なさま。','この模型は本物と見間違えるほど精巧に作られている。','이 모형은 진짜와 착각할 정도로 정교하게 만들어져 있다.'),
('n1-2379','2026-11-24','鬱陶しい','うっとうしい','답답하다; 우울하고 성가시다; 후덥지근하고 꿉꿉하다','気分が重く晴れない。また、天候などがじめじめして不快である。','雨の日が続いて、なんとなく鬱陶しい気分だ。','비 오는 날이 계속되어 왠지 답답한 기분이다.'),
('n1-2380','2026-11-24','ちょくちょく','ちょくちょく','자주; 종종; 때때로','それほど間を置かず、何度も行われるさま。','彼とは仕事の関係でちょくちょく会う。','그와는 일 때문에 종종 만난다.'),
('n1-2386','2026-11-24','見苦しい','みぐるしい','보기 흉하다; 추하다; 꼴사납다','見た目・態度・行動などがみっともなく、不快に感じられる。','責任を押し付け合う姿は見苦しい。','서로 책임을 떠넘기는 모습은 보기 흉하다.'),
('n1-2393','2026-11-24','清々しい','すがすがしい','상쾌하다; 후련하다; 청량하다','心や気分が晴れ、さっぱりして気持ちがよい。','運動した後は清々しい気分になった。','운동한 뒤에는 상쾌한 기분이 들었다.'),
('n1-2414','2026-11-24','ぞんざい','ぞんざい','건성으로; 함부로; 무성의하게','扱い・言葉遣いなどが丁寧でなく、粗末でいい加減なさま。','お客様にぞんざいな言葉遣いをしてはいけない。','손님에게 무성의하고 함부로 말해서는 안 된다.'),
('n1-2463','2026-11-25','且つ','かつ','그리고; 또한; 동시에','二つの事柄が並行して成り立つことを示す語。そして、そのうえ。','この方法は簡単で、且つ効果も高い。','이 방법은 간단하면서도 효과도 높다.'),
('n1-2502','2026-11-25','ちらっと','ちらっと','힐끗; 언뜻; 잠깐','ほんの一瞬見る、または見えるさま。','通りすがりに店の中をちらっと見た。','지나가면서 가게 안을 힐끗 봤다.'),
('n1-2546','2026-11-25','努めて','つとめて','애써; 되도록; 가능한 한 노력하여','意識して努力し、できるだけそうするさま。','会議では努めて冷静に話すようにした。','회의에서는 애써 냉정하게 말하려고 했다.'),
('n1-2559','2026-11-25','折り返す','おりかえす','되돌아가다; 접어 되돌리다; 회신하다','進んできた方向を反対にして戻る。また、紙などを折って返す。','終点で電車が折り返す。','종점에서 전철이 되돌아간다.'),
('n1-2574','2026-11-25','きちっと','きちっと','정확히; 반듯하게; 빈틈없이','正確に、きちんと整っているさま。','書類は期限までにきちっと提出してください。','서류는 기한까지 정확히 제출해 주세요.'),
('n1-2576','2026-11-25','長大','ちょうだい','매우 길고 큼; 장대함','非常に長く、大きいこと。','長大な橋が海峡に架けられている。','매우 긴 다리가 해협에 놓여 있다.'),
('n1-2587','2026-11-25','即座に','そくざに','즉시; 즉각; 바로','その場ですぐに。間を置かずに。','質問に即座に答えた。','질문에 즉시 대답했다.'),
('n1-2590','2026-11-25','華美','かび','화려함; 지나치게 화려함','華やかで美しいこと。特に、必要以上に派手なこと。','式典では華美な服装を避けるよう求められた。','행사에서는 지나치게 화려한 복장을 피하도록 요구받았다.'),
('n1-2607','2026-11-25','丸っきり','まるっきり','완전히; 전혀; 도무지','完全に。特に否定表現とともに『全然』の意味で使う。','その話は丸っきりの嘘だった。','그 이야기는 완전한 거짓말이었다.'),
('n1-2615','2026-11-25','罵る','ののしる','욕하다; 매도하다; 험담하다','相手を激しい言葉で非難・侮辱する。','人前で相手を罵るような行為はよくない。','사람들 앞에서 상대를 욕하는 행동은 좋지 않다.'),
('n1-2620','2026-11-25','しみじみ','しみじみ','절실히; 새삼스럽게; 깊이','心に深く感じ入るさま。じっくりと味わうさま。','家族のありがたさをしみじみ感じた。','가족의 소중함을 새삼 깊이 느꼈다.'),
('n1-2634','2026-11-25','華々しい','はなばなしい','화려하다; 눈부시다; 장대하다','非常に華やかで目立ち、立派である。','彼は華々しいデビューを飾った。','그는 화려한 데뷔를 장식했다.'),
('n1-2657','2026-11-25','待ち遠しい','まちどおしい','손꼽아 기다려지다; 몹시 기다려지다','その時・出来事が早く来てほしいと強く期待する。','家族に会える日が待ち遠しい。','가족을 만날 날이 손꼽아 기다려진다.'),
('n1-2679','2026-11-25','無闇に','むやみに','함부로; 무턱대고; 마구','よく考えず、度を越して行うさま。','知らないリンクを無闇に開かないほうがいい。','모르는 링크를 함부로 열지 않는 편이 좋다.'),
('n1-2706','2026-11-25','煌びやか','きらびやか','화려하다; 눈부시게 아름답다','華やかで、きらきらと美しく目立つさま。','会場は煌びやかな照明で飾られていた。','행사장은 화려한 조명으로 장식되어 있었다.'),
('n1-2709','2026-11-25','心細い','こころぼそい','불안하다; 의지할 곳 없어 외롭다; 막막하다','頼るものがなく、不安で心もとない。','知らない土地で一人暮らしを始めるのは少し心細い。','낯선 곳에서 혼자 살기 시작하는 것은 조금 불안하다.'),
('n1-2715','2026-11-25','生臭い','なまぐさい','비리다; 피비린내 나다','生魚・生肉・血などのような嫌なにおいがする。','台所に生臭いにおいが残っていた。','주방에 비린내가 남아 있었다.'),
('n1-2716','2026-11-25','先だって','せんだって','얼마 전; 지난번에','少し前。先日。','先だってお話しした件について連絡します。','얼마 전 말씀드린 건에 대해 연락드립니다.'),
('n1-2724','2026-11-25','慌ただしい','あわただしい','분주하다; 부산하다; 급박하다','忙しく、落ち着かないさま。','年末は毎年慌ただしい日が続く。','연말에는 매년 분주한 날이 이어진다.'),
('n1-2727','2026-11-25','薄弱','はくじゃく','박약; 빈약; 약함','意志・根拠・体力などが弱く十分でないこと。','その主張は根拠が薄弱だ。','그 주장은 근거가 빈약하다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-11-12..2026-11-25' FROM _n1_b4_words_0103 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b4_map_0103(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b4_words_0103 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
