INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1342","prompt":"「悟る」の読み方として最も適切なものを選びなさい。","options":["けがす","かきとる","はがす","さとる"],"answer":"さとる","explanationKo":"「悟る」는 「さとる」라고 읽는다. 뜻은 깨닫다; 알아차리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1349","prompt":"「絶える」の読み方として最も適切なものを選びなさい。","options":["くみこむ","はげます","たえる","とりもどす"],"answer":"たえる","explanationKo":"「絶える」는 「たえる」라고 읽는다. 뜻은 끊기다; 사라지다; 끝나다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1351","prompt":"「取り戻す」の読み方として最も適切なものを選びなさい。","options":["とじる","とりもどす","おりかえす","さっする"],"answer":"とりもどす","explanationKo":"「取り戻す」는 「とりもどす」라고 읽는다. 뜻은 되찾다; 회복하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1347","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n展望台から市街地を（　）と、川の流れまでよく見えた。","options":["見渡す","引っ掛ける","老いる","和らげる"],"answer":"見渡す","explanationKo":"문맥상 「見渡す」가 가장 자연스럽다. 둘러보다; 멀리까지 바라보다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1353","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）な姿勢を評価され、重要な業務を任された。","options":["ぞんざい","渋い","下らない","勤勉"],"answer":"勤勉","explanationKo":"문맥상 「勤勉」가 가장 자연스럽다. 근면함; 성실히 노력함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1356","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n機能を増やすことより、（　）なのは安定して動くことだ。","options":["月並み","且つ","肝心","少なくとも"],"answer":"肝心","explanationKo":"문맥상 「肝心」가 가장 자연스럽다. 가장 중요함; 핵심라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1359","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n戦争が市民にもたらした（　）な現実が記録に残されている。","options":["無茶苦茶","残酷","ちょくちょく","慌ただしい"],"answer":"残酷","explanationKo":"문맥상 「残酷」가 가장 자연스럽다. 잔혹함; 무자비함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1364","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n関係部署と議論を重ね、実施計画をさらに（　）必要がある。","options":["練る","尊ぶ","据える","恥じる"],"answer":"練る","explanationKo":"문맥상 「練る」가 가장 자연스럽다. 다듬다; 숙고하다; 반죽하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1373","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n雨の日が続くと、少し（　）な気分になることがある。","options":["酷い","ぶらぶら","漠然","憂鬱"],"answer":"憂鬱","explanationKo":"문맥상 「憂鬱」가 가장 자연스럽다. 우울함; 마음이 무거움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1384","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明は簡潔で（　）だったため、参加者から質問はほとんど出なかった。","options":["軒並み","丸っきり","明瞭","相変わらず"],"answer":"明瞭","explanationKo":"문맥상 「明瞭」가 가장 자연스럽다. 명료함; 분명함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1370","prompt":"「騒ぎ・怒り・勢いなどが静かになる。また、物が一定の場所や範囲の中に入る。」という意味に最も近い語を選びなさい。","options":["売り出す","収まる","葬る","賑わう"],"answer":"収まる","explanationKo":"「収まる」의 핵심 의미는 가라앉다; 진정되다; 제자리에 들어가다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1405","prompt":"「人・物を自分の側で受け持つために受け取る。また、預けた物を受け取って持ち帰る。」という意味に最も近い語を選びなさい。","options":["引き取る","弄る","改まる","待ち望む"],"answer":"引き取る","explanationKo":"「引き取る」의 핵심 의미는 인수하다; 맡아 데려가다; 회수하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1426","prompt":"「眠りから覚める。また、今まで意識していなかった価値・思想・能力などに気づく。」という意味に最も近い語を選びなさい。","options":["強まる","賑わう","代わる","目覚める"],"answer":"目覚める","explanationKo":"「目覚める」의 핵심 의미는 잠에서 깨다; 눈뜨다; 자각하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1450","prompt":"「目的地へ行く途中などで、別の場所に短時間寄る。」という意味に最も近い語を選びなさい。","options":["途絶える","備え付ける","立ち寄る","弱める"],"answer":"立ち寄る","explanationKo":"「立ち寄る」의 핵심 의미는 들르다; 잠깐 방문하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1474","prompt":"「乗り物の中へ入って乗る。また、勢いよく特定の場所へ入っていく。」という意味に最も近い語を選びなさい。","options":["組み込む","乗り込む","ぶら下げる","悟る"],"answer":"乗り込む","explanationKo":"「乗り込む」의 핵심 의미는 올라타다; 들어가다; 현장에 직접 들어가다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','grammar',1,'〜が最後','{"pattern":"〜が最後","meaningKo":"〜하면 그것으로 끝","explanation":"〜が最後는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は一度話し始めたが最後、こちらが止めるまで話し続ける。","ko":"문맥에서 〜하면 그것으로 끝의 의미로 쓰였다."},{"ja":"その秘密を口にしたが最後、以前の関係には戻れない。","ko":"이 문장도 〜하면 그것으로 끝의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','grammar',2,'〜かたわら','{"pattern":"〜かたわら","meaningKo":"〜하는 한편","explanation":"〜かたわら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼女は会社で働くかたわら、地域の子どもに日本語を教えている。","ko":"문맥에서 〜하는 한편의 의미로 쓰였다."},{"ja":"研究を続けるかたわら、専門誌の編集にも携わっている。","ko":"이 문장도 〜하는 한편의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は一度話し始めた（　）、こちらが止めるまで話し続ける。","options":["〜が最後","〜や否や","〜といったらありはしない","〜にかかわる"],"answer":"〜が最後","explanationKo":"문맥상 〜하면 그것으로 끝를 나타내는 「〜が最後」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼女は会社で働く（　）、地域の子どもに日本語を教えている。","options":["〜だろうに","〜としたところで","〜にしてからが","〜かたわら"],"answer":"〜かたわら","explanationKo":"문맥상 〜하는 한편를 나타내는 「〜かたわら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n出張（　）、以前の取引先にも挨拶した。","options":["〜ともあろうものが","〜に忍びない","〜がてら","〜てはかなわない"],"answer":"〜がてら","explanationKo":"문맥상 〜하는 김에를 나타내는 「〜がてら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-12','reading',1,'前例を使う条件','{"passage":"過去の前例を判断に使うことには、検討の出発点を早く定められることという利点がある。一方で、条件の違いを無視すると誤った結論になることも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、共通点だけでなく相違点も明示することが重要なのである。","questions":[{"prompt":"「前例を使う条件」について筆者が重視していることは何か。","options":["共通点だけでなく相違点も明示すること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"共通点だけでなく相違点も明示すること","explanationKo":"본문에서는 共通点だけでなく相違点も明示すること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["条件の違いを無視すると誤った結論になること","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"条件の違いを無視すると誤った結論になること","explanationKo":"주의점은 条件の違いを無視すると誤った結論になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["検討の出発点を早く定められること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"検討の出発点を早く定められること","explanationKo":"過去の前例を判断に使うこと에는 検討の出発点を早く定められること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1619","prompt":"「苦しめる」の読み方として最も適切なものを選びなさい。","options":["くるしめる","めぐむ","さしかかる","もうしでる"],"answer":"くるしめる","explanationKo":"「苦しめる」는 「くるしめる」라고 읽는다. 뜻은 괴롭히다; 고통을 주다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1621","prompt":"「染まる」の読み方として最も適切なものを選びなさい。","options":["やしなう","おしむ","みおとす","そまる"],"answer":"そまる","explanationKo":"「染まる」는 「そまる」라고 읽는다. 뜻은 물들다; 영향을 받아 동화되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1624","prompt":"「操る」の読み方として最も適切なものを選びなさい。","options":["ひきずる","ねだる","あやつる","おしこむ"],"answer":"あやつる","explanationKo":"「操る」는 「あやつる」라고 읽는다. 뜻은 조종하다; 다루다; 마음대로 움직이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1392","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n多様な文章を読むことで、物事を批判的に考える力を（　）ことができる。","options":["慌てる","養う","似通う","交わる"],"answer":"養う","explanationKo":"문맥상 「養う」가 가장 자연스럽다. 기르다; 부양하다; 함양하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1407","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその地方では、この鳥の鳴き声を（　）な兆しと考える言い伝えがある。","options":["不吉","精巧","逞しい","何より"],"answer":"不吉","explanationKo":"문맥상 「不吉」가 가장 자연스럽다. 불길함; 좋지 않은 징조라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1420","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）だが、必要な時には的確な意見を述べる。","options":["殊に","丸ごと","清々しい","無口"],"answer":"無口","explanationKo":"문맥상 「無口」가 가장 자연스럽다. 말수가 적음; 과묵함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1424","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n重要な変更は本番直前ではなく、十分な検証期間を取って行うのが（　）。","options":["煌びやか","喧しい","望ましい","何卒"],"answer":"望ましい","explanationKo":"문맥상 「望ましい」가 가장 자연스럽다. 바람직하다; 이상적이다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1427","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n締切を過ぎてから（　）条件を変えるのは難しい。","options":["滑らか","今更","くっきり","努めて"],"answer":"今更","explanationKo":"문맥상 「今更」가 가장 자연스럽다. 이제 와서; 새삼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1431","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n本人は真剣だったが、周囲から見ると少し（　）な光景だった。","options":["滑稽","到底","尊い","粋"],"answer":"滑稽","explanationKo":"문맥상 「滑稽」가 가장 자연스럽다. 우스꽝스러움; 익살스러움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1445","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの人数では今日中に全件を確認するのは（　）無理だ。","options":["寛容","健やか","ぞんざい","到底"],"answer":"到底","explanationKo":"문맥상 「到底」가 가장 자연스럽다. 도저히; 아무리 해도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1633","prompt":"「思いどおりに進まないことなどで落ち着きを失い、急いで何とかしようとする。」という意味に最も近い語を選びなさい。","options":["腫れる","収まる","焦る","捕らえる"],"answer":"焦る","explanationKo":"「焦る」의 핵심 의미는 초조해하다; 조급해하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1644","prompt":"「気分・成績・売上などが低下する。また、表面が周囲より低くへこむ。」という意味に最も近い語を選びなさい。","options":["抜け出す","落ち込む","練る","騙す"],"answer":"落ち込む","explanationKo":"「落ち込む」의 핵심 의미는 낙담하다; 침체되다; 움푹 들어가다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1645","prompt":"「指先で物の一部を挟んで持つ。」という意味に最も近い語を選びなさい。","options":["摘む","挑む","漏る","危ぶむ"],"answer":"摘む","explanationKo":"「摘む」의 핵심 의미는 집다; 꼬집듯 집어 올리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1677","prompt":"「あまりにひどい・意外なことに驚き、言葉を失うほどになる。」という意味に最も近い語を選びなさい。","options":["収まる","臨む","抜け出す","呆れる"],"answer":"呆れる","explanationKo":"「呆れる」의 핵심 의미는 기가 막히다; 어이없어하다; 질리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1706","prompt":"「人を横にして眠らせる。また、物・計画などを一定期間そのまま置く。」という意味に最も近い語を選びなさい。","options":["書き取る","剥がす","寝かせる","面する"],"answer":"寝かせる","explanationKo":"「寝かせる」의 핵심 의미는 눕히다; 재우다; 숙성시키다; 당분간 묵혀 두다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','grammar',1,'〜がてら','{"pattern":"〜がてら","meaningKo":"〜하는 김에","explanation":"〜がてら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"散歩がてら、図書館まで本を返しに行った。","ko":"문맥에서 〜하는 김에의 의미로 쓰였다."},{"ja":"出張がてら、以前の取引先にも挨拶した。","ko":"이 문장도 〜하는 김에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','grammar',2,'〜がゆえに','{"pattern":"〜がゆえに","meaningKo":"〜이기 때문에","explanation":"〜がゆえに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"責任感が強いがゆえに、仕事を一人で抱え込んでしまう。","ko":"문맥에서 〜이기 때문에의 의미로 쓰였다."},{"ja":"便利であるがゆえに、その危険性が見落とされやすい。","ko":"이 문장도 〜이기 때문에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n散歩（　）、図書館まで本を返しに行った。","options":["〜てはかなわない","〜ともあろうものが","〜に忍びない","〜がてら"],"answer":"〜がてら","explanationKo":"문맥상 〜하는 김에를 나타내는 「〜がてら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任感が強い（　）、仕事を一人で抱え込んでしまう。","options":["〜ないものでもない","〜にひきずられて","〜がゆえに","〜てはばからない"],"answer":"〜がゆえに","explanationKo":"문맥상 〜이기 때문에를 나타내는 「〜がゆえに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n何事もなかった（　）、彼は会議を続けた。","options":["〜にもほどがある","〜ごとく","〜てまで","〜なり"],"answer":"〜ごとく","explanationKo":"문맥상 〜처럼를 나타내는 「〜ごとく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-13','reading',1,'説明の順序を設計する','{"passage":"複雑な内容の説明順を工夫することには、聞き手が論理を追いやすくなることという利点がある。一方で、簡略化しすぎると重要な前提が抜けることも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、結論と根拠の関係が見える順に示すことが重要なのである。","questions":[{"prompt":"「説明の順序を設計する」について筆者が重視していることは何か。","options":["結論と根拠の関係が見える順に示すこと","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"結論と根拠の関係が見える順に示すこと","explanationKo":"본문에서는 結論と根拠の関係が見える順に示すこと 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["簡略化しすぎると重要な前提が抜けること","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"簡略化しすぎると重要な前提が抜けること","explanationKo":"주의점은 簡略化しすぎると重要な前提が抜けること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["聞き手が論理を追いやすくなること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"聞き手が論理を追いやすくなること","explanationKo":"複雑な内容の説明順を工夫すること에는 聞き手が論理を追いやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1963","prompt":"「相応しい」の読み方として最も適切なものを選びなさい。","options":["ふじゅん","ふさわしい","ざんこく","かみつ"],"answer":"ふさわしい","explanationKo":"「相応しい」는 「ふさわしい」라고 읽는다. 뜻은 알맞다; 적합하다; 어울리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
