INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1464","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n晴れていた空が（　）暗くなり、激しい雨が降り始めた。","options":["突如","几帳面","苛々","夥しい"],"answer":"突如","explanationKo":"문맥상 「突如」가 가장 자연스럽다. 돌연; 갑자기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1470","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n屋外で使う装置なので、雨や衝撃に耐える（　）なケースを選んだ。","options":["卑しい","生臭い","過密","頑丈"],"answer":"頑丈","explanationKo":"문맥상 「頑丈」가 가장 자연스럽다. 튼튼함; 견고함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1476","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n部門間の情報共有を改善し、業務を（　）に進められるようにした。","options":["貧弱","突如","円滑","頑固"],"answer":"円滑","explanationKo":"문맥상 「円滑」가 가장 자연스럽다. 원활함; 순조로움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1484","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予定どおり九時（　）に会議が始まった。","options":["あやふや","きっちり","無口","悲惨"],"answer":"きっちり","explanationKo":"문맥상 「きっちり」가 가장 자연스럽다. 딱 맞게; 정확히; 빈틈없이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1487","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者に誤解を与えないよう、より（　）表現に修正した。","options":["好ましい","何より","健やか","ちらっと"],"answer":"好ましい","explanationKo":"문맥상 「好ましい」가 가장 자연스럽다. 바람직하다; 호감이 간다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1973","prompt":"「死者を埋葬する。また、事実・計画などを表に出ないようにする。」という意味に最も近い語を選びなさい。","options":["治まる","目覚める","漏れる","葬る"],"answer":"葬る","explanationKo":"「葬る」의 핵심 의미는 매장하다; 묻다; 묻어 버리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1990","prompt":"「雰囲気・気運などが活発になる。また、形が高くふくらむ。」という意味に最も近い語を選びなさい。","options":["綴じる","揉める","盛り上がる","察する"],"answer":"盛り上がる","explanationKo":"「盛り上がる」의 핵심 의미는 고조되다; 달아오르다; 부풀어 오르다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1995","prompt":"「神・人などに物を差し出す。また、時間・人生などをある目的に尽くす。」という意味に最も近い語を選びなさい。","options":["漏れる","捧げる","呟く","折り返す"],"answer":"捧げる","explanationKo":"「捧げる」의 핵심 의미는 바치다; 헌신하다; 올리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1998","prompt":"「力・程度・勢いなどが強くなる。」という意味に最も近い語を選びなさい。","options":["強まる","染まる","舞う","食い違う"],"answer":"強まる","explanationKo":"「強まる」의 핵심 의미는 강해지다; 거세지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1999","prompt":"「相手の方へ物を出す。また、書類などを提出する。」という意味に最も近い語を選びなさい。","options":["打ち切る","跨ぐ","恵む","差し出す"],"answer":"差し出す","explanationKo":"「差し出す」의 핵심 의미는 내밀다; 제출하다; 내놓다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','grammar',1,'〜ごとく','{"pattern":"〜ごとく","meaningKo":"〜처럼","explanation":"〜ごとく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"予想したごとく、交渉は難航した。","ko":"문맥에서 〜처럼의 의미로 쓰였다."},{"ja":"何事もなかったごとく、彼は会議を続けた。","ko":"이 문장도 〜처럼의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','grammar',2,'〜や否や','{"pattern":"〜や否や","meaningKo":"〜하자마자","explanation":"〜や否や는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"知らせを聞くや否や、担当者は現場へ向かった。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"結果が判明するや否や、関係部署に連絡した。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n予想した（　）、交渉は難航した。","options":["〜なり","〜にもほどがある","〜ごとく","〜てまで"],"answer":"〜ごとく","explanationKo":"문맥상 〜처럼를 나타내는 「〜ごとく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n知らせを聞く（　）、担当者は現場へ向かった。","options":["〜ばそれまでだ","〜や否や","〜といい〜といい","〜なりとも"],"answer":"〜や否や","explanationKo":"문맥상 〜하자마자를 나타내는 「〜や否や」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nもう少し確認すれば、誤りに気づいた（　）。","options":["〜だろうに","〜といったらありはしない","〜なり〜なり","〜べからざる"],"answer":"〜だろうに","explanationKo":"문맥상 〜일 텐데를 나타내는 「〜だろうに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-14','reading',1,'余白のある予定','{"passage":"予定に余白を持たせることには、予期しない作業にも対応できることという利点がある。一方で、目的なく時間を使えば単なる遅れになることも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、何の不確実性に備える余白かを決めることが重要なのである。","questions":[{"prompt":"「余白のある予定」について筆者が重視していることは何か。","options":["何の不確実性に備える余白かを決めること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"何の不確実性に備える余白かを決めること","explanationKo":"본문에서는 何の不確実性に備える余白かを決めること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["目的なく時間を使えば単なる遅れになること","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"目的なく時間を使えば単なる遅れになること","explanationKo":"주의점은 目的なく時間を使えば単なる遅れになること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["予期しない作業にも対応できること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"予期しない作業にも対応できること","explanationKo":"予定に余白を持たせること에는 予期しない作業にも対応できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2030","prompt":"「据える」の読み方として最も適切なものを選びなさい。","options":["ばける","あやつる","すえる","もうしいれる"],"answer":"すえる","explanationKo":"「据える」는 「すえる」라고 읽는다. 뜻은 설치하다; 놓다; 앉히다; 정하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
