INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1516","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n都市部では人口の（　）が交通や住宅の問題を深刻化させている。","options":["頑丈","あやふや","酷い","過密"],"answer":"過密","explanationKo":"문맥상 「過密」가 가장 자연스럽다. 과밀라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1519","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明不足は利用者の信頼を（　）原因になりかねない。","options":["洒落る","見渡す","損なう","怯える"],"answer":"損なう","explanationKo":"문맥상 「損なう」가 가장 자연스럽다. 손상시키다; 해치다; 잃게 하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1524","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事実ではない発言で故人の名誉を（　）べきではない。","options":["損なう","汚す","咎める","焦る"],"answer":"汚す","explanationKo":"문맥상 「汚す」가 가장 자연스럽다. 더럽히다; 훼손하다; 모독하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2042","prompt":"「ある方向・場所に正面を向けて接している。」という意味に最も近い語を選びなさい。","options":["面する","説く","損なう","賑わう"],"answer":"面する","explanationKo":"「面する」의 핵심 의미는 면하다; 마주하다; 접하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2043","prompt":"「急な出来事に驚き、落ち着きを失う。」という意味に最も近い語を選びなさい。","options":["見渡す","説く","唸る","慌てる"],"answer":"慌てる","explanationKo":"「慌てる」의 핵심 의미는 당황하다; 허둥대다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2044","prompt":"「ある性質・色・雰囲気などを含んで持つ。また、任務などを受け持つ。」という意味に最も近い語を選びなさい。","options":["揺らぐ","漕ぐ","帯びる","損なう"],"answer":"帯びる","explanationKo":"「帯びる」의 핵심 의미는 띠다; 지니다; 맡다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2059","prompt":"「物を一列につなげたり並べたりする。また、名を列に加える。」という意味に最も近い語を選びなさい。","options":["交わる","連ねる","拘る","寄越す"],"answer":"連ねる","explanationKo":"「連ねる」의 핵심 의미는 잇다; 나란히 늘어놓다; 이름을 올리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2061","prompt":"「事情・気持ちなどを推測して理解する。」という意味に最も近い語を選びなさい。","options":["察する","乱す","収まる","呆れる"],"answer":"察する","explanationKo":"「察する」의 핵심 의미는 헤아리다; 짐작하다; 알아차리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','grammar',1,'〜だろうに','{"pattern":"〜だろうに","meaningKo":"〜일 텐데","explanation":"〜だろうに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事前に相談してくれれば協力できただろうに。","ko":"문맥에서 〜일 텐데의 의미로 쓰였다."},{"ja":"もう少し確認すれば、誤りに気づいただろうに。","ko":"이 문장도 〜일 텐데의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','grammar',2,'〜てはかなわない','{"pattern":"〜てはかなわない","meaningKo":"〜해서는 견딜 수 없다","explanation":"〜てはかなわない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"毎晩工事の音が続いてはかなわない。","ko":"문맥에서 〜해서는 견딜 수 없다의 의미로 쓰였다."},{"ja":"急な予定変更を何度もされてはかなわない。","ko":"이 문장도 〜해서는 견딜 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事前に相談してくれれば協力できた（　）。","options":["〜べからざる","〜だろうに","〜といったらありはしない","〜なり〜なり"],"answer":"〜だろうに","explanationKo":"문맥상 〜일 텐데를 나타내는 「〜だろうに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n毎晩工事の音が続い（　）。","options":["〜てはかなわない","〜としたところで","〜にあたらない","〜めく"],"answer":"〜てはかなわない","explanationKo":"문맥상 〜해서는 견딜 수 없다를 나타내는 「〜てはかなわない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその評論家は制度全体が失敗だと断言し（　）。","options":["〜ともあろうものが","〜にかかわる","〜をおいて","〜てはばからない"],"answer":"〜てはばからない","explanationKo":"문맥상 거리낌 없이 〜하다를 나타내는 「〜てはばからない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-15','reading',1,'少数意見の役割','{"passage":"少数意見を検討することには、多数が見落とした条件を発見できることという利点がある。一方で、人数だけで価値を判断すると論点を失うことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、意見の根拠を決定条件と照合することが重要なのである。","questions":[{"prompt":"「少数意見の役割」について筆者が重視していることは何か。","options":["意見の根拠を決定条件と照合すること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"意見の根拠を決定条件と照合すること","explanationKo":"본문에서는 意見の根拠を決定条件と照合すること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["人数だけで価値を判断すると論点を失うこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"人数だけで価値を判断すると論点を失うこと","explanationKo":"주의점은 人数だけで価値を判断すると論点を失うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["多数が見落とした条件を発見できること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"多数が見落とした条件を発見できること","explanationKo":"少数意見を検討すること에는 多数が見落とした条件を発見できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2118","prompt":"「付け加える」の読み方として最も適切なものを選びなさい。","options":["にじむ","くるしめる","しいれる","つけくわえる"],"answer":"つけくわえる","explanationKo":"「付け加える」는 「つけくわえる」라고 읽는다. 뜻은 덧붙이다; 추가하다; 부가하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
