INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1553","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n引っ越しの準備には（　）一週間かかった。","options":["丸々","ぶらぶら","ずるずる","望ましい"],"answer":"丸々","explanationKo":"문맥상 「丸々」가 가장 자연스럽다. 통째로; 전부; 꼬박라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1556","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n根拠のない数字を並べた（　）な計画では承認されない。","options":["煌びやか","物足りない","恐らく","無茶苦茶"],"answer":"無茶苦茶","explanationKo":"문맥상 「無茶苦茶」가 가장 자연스럽다. 엉망진창; 터무니없음; 무리함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1559","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n景気の停滞から（　）には、新しい需要を生み出す必要がある。","options":["重んじる","心掛ける","抜け出す","面する"],"answer":"抜け出す","explanationKo":"문맥상 「抜け出す」가 가장 자연스럽다. 빠져나오다; 벗어나다; 탈출하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2146","prompt":"「人が多く集まり活気に満ちる。また、商売などが繁盛する。」という意味に最も近い語を選びなさい。","options":["養う","賑わう","申し入れる","害する"],"answer":"賑わう","explanationKo":"「賑わう」의 핵심 의미는 붐비다; 번성하다; 활기를 띠다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2160","prompt":"「一つの方針・立場などを最後まで貫く。また、一つのことに徹底して打ち込む。」という意味に最も近い語を選びなさい。","options":["徹する","取り戻す","摘む","浸す"],"answer":"徹する","explanationKo":"「徹する」의 핵심 의미는 철저히 하다; 관철하다; 몰두하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2166","prompt":"「申し込み・依頼・質問などを受け取って対応する。また、人や物事を受け入れる。」という意味に最も近い語を選びなさい。","options":["聳える","咎める","焦る","受け付ける"],"answer":"受け付ける","explanationKo":"「受け付ける」의 핵심 의미는 접수하다; 받아들이다; 받다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2195","prompt":"「速く走る。特に人や馬などが勢いよく走る。」という意味に最も近い語を選びなさい。","options":["浸す","偏る","駆ける","養う"],"answer":"駆ける","explanationKo":"「駆ける」의 핵심 의미는 달리다; 뛰어가다; 질주하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2196","prompt":"「体・精神などが強く、力に満ちている。」という意味に最も近い語を選びなさい。","options":["待ち遠しい","逞しい","努めて","物足りない"],"answer":"逞しい","explanationKo":"「逞しい」의 핵심 의미는 튼튼하다; 우람하다; 늠름하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','grammar',1,'〜てはばからない','{"pattern":"〜てはばからない","meaningKo":"거리낌 없이 〜하다","explanation":"〜てはばからない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は自分こそ適任だと言ってはばからない。","ko":"문맥에서 거리낌 없이 〜하다의 의미로 쓰였다."},{"ja":"その評論家は制度全体が失敗だと断言してはばからない。","ko":"이 문장도 거리낌 없이 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','grammar',2,'〜てまで','{"pattern":"〜てまで","meaningKo":"〜해서까지","explanation":"〜てまで는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"健康を犠牲にしてまで働く必要はない。","ko":"문맥에서 〜해서까지의 의미로 쓰였다."},{"ja":"規則を曲げてまで成果を求めるべきではない。","ko":"이 문장도 〜해서까지의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は自分こそ適任だと言っ（　）。","options":["〜てはばからない","〜ともあろうものが","〜にかかわる","〜をおいて"],"answer":"〜てはばからない","explanationKo":"문맥상 거리낌 없이 〜하다를 나타내는 「〜てはばからない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n健康を犠牲にし（　）働く必要はない。","options":["〜ないものでもない","〜にしてからが","〜が最後","〜てまで"],"answer":"〜てまで","explanationKo":"문맥상 〜해서까지를 나타내는 「〜てまで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n内容（　）、十分に練られた報告書だ。","options":["〜に忍びない","〜かたわら","〜といい〜といい","〜なり"],"answer":"〜といい〜といい","explanationKo":"문맥상 〜도 그렇고 〜도 그렇고를 나타내는 「〜といい〜といい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-16','reading',1,'自動化後の確認','{"passage":"作業を自動化することには、反復作業の負担と誤りを減らせることという利点がある。一方で、例外まで機械に任せると異常を見逃すことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、人が確認すべき境界を先に定めることが重要なのである。","questions":[{"prompt":"「自動化後の確認」について筆者が重視していることは何か。","options":["人が確認すべき境界を先に定めること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"人が確認すべき境界を先に定めること","explanationKo":"본문에서는 人が確認すべき境界を先に定めること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["例外まで機械に任せると異常を見逃すこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"例外まで機械に任せると異常を見逃すこと","explanationKo":"주의점은 例外まで機械に任せると異常を見逃すこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["反復作業の負担と誤りを減らせること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"反復作業の負担と誤りを減らせること","explanationKo":"作業を自動化すること에는 反復作業の負担と誤りを減らせること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2273","prompt":"「打ち切る」の読み方として最も適切なものを選びなさい。","options":["うちきる","めざめる","もれる","とらえる"],"answer":"うちきる","explanationKo":"「打ち切る」는 「うちきる」라고 읽는다. 뜻은 중단하다; 끝내다; 종결하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2275","prompt":"「重んじる」の読み方として最も適切なものを選びなさい。","options":["よわまる","けむる","めざめる","おもんじる"],"answer":"おもんじる","explanationKo":"「重んじる」는 「おもんじる」라고 읽는다. 뜻은 중시하다; 존중하다; 소중히 여기다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2283","prompt":"「引っ掛ける」の読み方として最も適切なものを選びなさい。","options":["もうしでる","とだえる","ひっかける","おりかえす"],"answer":"ひっかける","explanationKo":"「引っ掛ける」는 「ひっかける」라고 읽는다. 뜻은 걸다; 걸치다; 걸려들게 하다; 속이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1563","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予算案を示すと、部長は少し（　）顔をした。","options":["滑稽","渋い","酷い","卑しい"],"answer":"渋い","explanationKo":"문맥상 「渋い」가 가장 자연스럽다. 떫다; 탐탁지 않다; 차분하고 멋스럽다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1578","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n失敗そのものを（　）より、そこから学ぶ姿勢が大切だ。","options":["恥じる","練る","叶う","面する"],"answer":"恥じる","explanationKo":"문맥상 「恥じる」가 가장 자연스럽다. 부끄러워하다; 수치스럽게 여기다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1580","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長引く内戦によって住民の生活は（　）な状況に置かれた。","options":["頻りに","苛々","卑しい","悲惨"],"answer":"悲惨","explanationKo":"문맥상 「悲惨」가 가장 자연스럽다. 비참함; 참혹함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1599","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の反応は（　）ではなく、評価が大きく分かれた。","options":["待ち遠しい","円滑","一様","未練"],"answer":"一様","explanationKo":"문맥상 「一様」가 가장 자연스럽다. 한결같음; 동일함; 획일적임라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1613","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n特定の会社だけを優遇する（　）な対応には批判が集まった。","options":["今更","露骨","滑稽","寛容"],"answer":"露骨","explanationKo":"문맥상 「露骨」가 가장 자연스럽다. 노골적임; 숨김없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1617","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n情報源が一つに（　）と、判断も偏りやすくなる。","options":["偏る","強まる","病む","拘る"],"answer":"偏る","explanationKo":"문맥상 「偏る」가 가장 자연스럽다. 치우치다; 편중되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1629","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n荷物を無理に箱へ（　）と、中の商品が壊れるおそれがある。","options":["売り出す","嘆く","乱す","押し込む"],"answer":"押し込む","explanationKo":"문맥상 「押し込む」가 가장 자연스럽다. 밀어 넣다; 억지로 집어넣다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2317","prompt":"「値段が安そうに見え、品質・品格が低く感じられる。」という意味に最も近い語を選びなさい。","options":["薄弱","容易い","安っぽい","ずるずる"],"answer":"安っぽい","explanationKo":"「安っぽい」의 핵심 의미는 싸구려처럼 보이다; 값싸 보이다; 천박해 보이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2319","prompt":"「物がゆらゆらと動く。また、信念・地位・状態などが不安定になる。」という意味に最も近い語を選びなさい。","options":["衰える","揺らぐ","受け付ける","見掛ける"],"answer":"揺らぐ","explanationKo":"「揺らぐ」의 핵심 의미는 흔들리다; 동요하다; 불안정해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2322","prompt":"「一つにつながっていた物に切れ目が入り、二つ以上に分かれる。」という意味に最も近い語を選びなさい。","options":["裂ける","潤う","呆れる","仕入れる"],"answer":"裂ける","explanationKo":"「裂ける」의 핵심 의미는 찢어지다; 갈라지다; 터지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2330","prompt":"「何かが不足していて、十分に満足できない。」という意味に最も近い語を選びなさい。","options":["相変わらず","惨め","長大","物足りない"],"answer":"物足りない","explanationKo":"「物足りない」의 핵심 의미는 아쉽다; 뭔가 부족하다; 만족스럽지 않다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2339","prompt":"「恐怖を感じて怖がる。恐ろしさのために不安になる。」という意味に最も近い語を選びなさい。","options":["召す","差し出す","怯える","受け止める"],"answer":"怯える","explanationKo":"「怯える」의 핵심 의미는 겁먹다; 두려워하다; 무서워 떨다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','grammar',1,'〜といい〜といい','{"pattern":"〜といい〜といい","meaningKo":"〜도 그렇고 〜도 그렇고","explanation":"〜といい〜といい는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"色といい形といい、この器は見事な出来だ。","ko":"문맥에서 〜도 그렇고 〜도 그렇고의 의미로 쓰였다."},{"ja":"内容といい構成といい、十分に練られた報告書だ。","ko":"이 문장도 〜도 그렇고 〜도 그렇고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','grammar',2,'〜といったらありはしない','{"pattern":"〜といったらありはしない","meaningKo":"이루 말할 수 없이 〜하다","explanation":"〜といったらありはしない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"締切直前にデータが消えたときの焦りといったらありはしない。","ko":"문맥에서 이루 말할 수 없이 〜하다의 의미로 쓰였다."},{"ja":"根拠もなく責任を押しつけるとは、無責任といったらありはしない。","ko":"이 문장도 이루 말할 수 없이 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
