INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n締切直前にデータが消えたときの焦り（　）。","options":["〜にひきずられて","〜がてら","〜といったらありはしない","〜なりとも"],"answer":"〜といったらありはしない","explanationKo":"문맥상 이루 말할 수 없이 〜하다를 나타내는 「〜といったらありはしない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n担当者を替えた（　）、仕組みを直さなければ同じ問題が起きる。","options":["〜がゆえに","〜としたところで","〜なり〜なり","〜にもほどがある"],"answer":"〜としたところで","explanationKo":"문맥상 〜라고 해도를 나타내는 「〜としたところで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-17','reading',1,'期限を共有する意味','{"passage":"期限を関係者と共有することには、作業の順序と責任を調整しやすくなることという利点がある。一方で、日付だけ示すと必要な品質が伝わらないことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、完了条件と確認時間も一緒に決めることが重要なのである。","questions":[{"prompt":"「期限を共有する意味」について筆者が重視していることは何か。","options":["完了条件と確認時間も一緒に決めること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"完了条件と確認時間も一緒に決めること","explanationKo":"본문에서는 完了条件と確認時間も一緒に決めること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["日付だけ示すと必要な品質が伝わらないこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"日付だけ示すと必要な品質が伝わらないこと","explanationKo":"주의점은 日付だけ示すと必要な品質が伝わらないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["作業の順序と責任を調整しやすくなること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"作業の順序と責任を調整しやすくなること","explanationKo":"期限を関係者と共有すること에는 作業の順序と責任を調整しやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2402","prompt":"「急かす」の読み方として最も適切なものを選びなさい。","options":["おさまる","せかす","ゆらぐ","すくう"],"answer":"せかす","explanationKo":"「急かす」는 「せかす」라고 읽는다. 뜻은 재촉하다; 서두르게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2403","prompt":"「書き取る」の読み方として最も適切なものを選びなさい。","options":["かきとる","ねだる","おりかえす","さっする"],"answer":"かきとる","explanationKo":"「書き取る」는 「かきとる」라고 읽는다. 뜻은 받아 적다; 필기하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2405","prompt":"「漏る」の読み方として最も適切なものを選びなさい。","options":["あわてる","ひっかける","おいる","もる"],"answer":"もる","explanationKo":"「漏る」는 「もる」라고 읽는다. 뜻은 새다; 누출되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1648","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n窓を開けると（　）風が入り、部屋の空気が一変した。","options":["夥しい","今更","快い","望ましい"],"answer":"快い","explanationKo":"문맥상 「快い」가 가장 자연스럽다. 기분 좋다; 상쾌하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1649","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害現場で人命を守るために働く姿は（　）。","options":["貧弱","尊い","明瞭","何しろ"],"answer":"尊い","explanationKo":"문맥상 「尊い」가 가장 자연스럽다. 존귀하다; 매우 귀중하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1652","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）な性格で、作業記録を毎日欠かさず残している。","options":["几帳面","諄い","前もって","夥しい"],"answer":"几帳面","explanationKo":"문맥상 「几帳面」가 가장 자연스럽다. 꼼꼼함; 빈틈없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1653","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの装置は（　）な測定が必要な研究で使用されている。","options":["何卒","華々しい","頑丈","精密"],"answer":"精密","explanationKo":"문맥상 「精密」가 가장 자연스럽다. 정밀함; 정교함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1654","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n照明を変えたことで、（　）だった部屋の印象が明るくなった。","options":["軽快","望ましい","陰気","無口"],"answer":"陰気","explanationKo":"문맥상 「陰気」가 가장 자연스럽다. 음침함; 우울하고 어두운 분위기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1656","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n相手を傷つけないよう、（　）な表現で改善を求めた。","options":["下らない","婉曲","ぞんざい","渋い"],"answer":"婉曲","explanationKo":"문맥상 「婉曲」가 가장 자연스럽다. 완곡함; 에둘러 표현함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1671","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n休日は予定を決めず、商店街を（　）歩くことにした。","options":["ぶらぶら","陰気","清らか","卑しい"],"answer":"ぶらぶら","explanationKo":"문맥상 「ぶらぶら」가 가장 자연스럽다. 어슬렁어슬렁; 빈둥빈둥; 흔들흔들라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2406","prompt":"「膨らんでいたものが小さくなる。また、花などが張りを失ってしおれる。」という意味に最も近い語を選びなさい。","options":["励ます","弄る","改まる","萎む"],"answer":"萎む","explanationKo":"「萎む」의 핵심 의미는 시들다; 쪼그라들다; 오므라들다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2408","prompt":"「美しい服・装飾品などを身に着けて、華やかに装う。」という意味に最も近い語を選びなさい。","options":["澄ます","呆れる","着飾る","危ぶむ"],"answer":"着飾る","explanationKo":"「着飾る」의 핵심 의미는 화려하게 차려입다; 멋지게 꾸며 입다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2409","prompt":"「物に手を触れて動かしたり、少し変更したりする。」という意味に最も近い語を選びなさい。","options":["途絶える","弄る","染める","弱める"],"answer":"弄る","explanationKo":"「弄る」의 핵심 의미는 만지작거리다; 손대다; 건드리다; 고치다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2411","prompt":"「煙が目・鼻を刺激して苦しい。また、相手を気兼ねして近寄りにくい。」という意味に最も近い語を選びなさい。","options":["煙たい","恐らく","過多","きちっと"],"answer":"煙たい","explanationKo":"「煙たい」의 핵심 의미는 연기가 매캐하다; 어렵고 불편한 상대다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2413","prompt":"「体の一部の感覚が鈍くなり、びりびりする。また、強い感動に圧倒されることもある。」という意味に最も近い語を選びなさい。","options":["罵る","漏れる","禁じる","痺れる"],"answer":"痺れる","explanationKo":"「痺れる」의 핵심 의미는 저리다; 마비되다; 감각이 둔해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','grammar',1,'〜としたところで','{"pattern":"〜としたところで","meaningKo":"〜라고 해도","explanation":"〜としたところで는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今から急いだとしたところで、開始時刻には間に合わない。","ko":"문맥에서 〜라고 해도의 의미로 쓰였다."},{"ja":"担当者を替えたとしたところで、仕組みを直さなければ同じ問題が起きる。","ko":"이 문장도 〜라고 해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','grammar',2,'〜ともあろうものが','{"pattern":"〜ともあろうものが","meaningKo":"〜정도 되는 사람이","explanation":"〜ともあろうものが는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"専門家ともあろうものが、資料を確認せず断定してはいけない。","ko":"문맥에서 〜정도 되는 사람이의 의미로 쓰였다."},{"ja":"責任者ともあろうものが、説明を避けるとは情けない。","ko":"이 문장도 〜정도 되는 사람이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今から急いだ（　）、開始時刻には間に合わない。","options":["〜にもほどがある","〜がゆえに","〜としたところで","〜なり〜なり"],"answer":"〜としたところで","explanationKo":"문맥상 〜라고 해도를 나타내는 「〜としたところで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家（　）、資料を確認せず断定してはいけない。","options":["〜ごとく","〜ともあろうものが","〜にあたらない","〜ばそれまでだ"],"answer":"〜ともあろうものが","explanationKo":"문맥상 〜정도 되는 사람이를 나타내는 「〜ともあろうものが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n十分な時間があれば、完成させられ（　）。","options":["〜ないものでもない","〜にかかわる","〜べからざる","〜や否や"],"answer":"〜ないものでもない","explanationKo":"문맥상 못할 것도 없다를 나타내는 「〜ないものでもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-18','reading',1,'比較できる記録','{"passage":"作業結果を記録することには、以前との変化を確かめられることという利点がある。一方で、記録方法が毎回違うと比較が難しくなることも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、目的に必要な項目を一定の形式で残すことが重要なのである。","questions":[{"prompt":"「比較できる記録」について筆者が重視していることは何か。","options":["目的に必要な項目を一定の形式で残すこと","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"目的に必要な項目を一定の形式で残すこと","explanationKo":"본문에서는 目的に必要な項目を一定の形式で残すこと 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["記録方法が毎回違うと比較が難しくなること","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"記録方法が毎回違うと比較が難しくなること","explanationKo":"주의점은 記録方法が毎回違うと比較が難しくなること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["以前との変化を確かめられること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"以前との変化を確かめられること","explanationKo":"作業結果を記録すること에는 以前との変化を確かめられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2548","prompt":"「背く」の読み方として最も適切なものを選びなさい。","options":["やしなう","ひたす","そむく","がいする"],"answer":"そむく","explanationKo":"「背く」는 「そむく」라고 읽는다. 뜻은 거스르다; 어기다; 배반하다; 등지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2557","prompt":"「頻りに」の読み方として最も適切なものを選びなさい。","options":["がっくり","しきりに","むちゃくちゃ","けいかい"],"answer":"しきりに","explanationKo":"「頻りに」는 「しきりに」라고 읽는다. 뜻은 자꾸; 빈번히; 연거푸; 열심히이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2558","prompt":"「禁じる」の読み方として最も適切なものを選びなさい。","options":["きんじる","とがめる","あせる","そこなう"],"answer":"きんじる","explanationKo":"「禁じる」는 「きんじる」라고 읽는다. 뜻은 금하다; 금지하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1672","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nメーカーは来月、新型端末を全国で（　）予定だ。","options":["取り巻く","捧げる","叶える","売り出す"],"answer":"売り出す","explanationKo":"문맥상 「売り出す」가 가장 자연스럽다. 판매를 시작하다; 내놓다; 널리 알리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1673","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な音楽に合わせて参加者が歩き始めた。","options":["相応しい","代わる代わる","軽快","健やか"],"answer":"軽快","explanationKo":"문맥상 「軽快」가 가장 자연스럽다. 경쾌함; 가볍고 산뜻함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1676","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n多様な価値観に（　）な組織ほど意見交換が活発になりやすい。","options":["ずるずる","寛容","煙たい","鈍感"],"answer":"寛容","explanationKo":"문맥상 「寛容」가 가장 자연스럽다. 관용; 너그러움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
