INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1693","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n責任の範囲を（　）にしたまま作業を始めるべきではない。","options":["不吉","陰気","煌びやか","あやふや"],"answer":"あやふや","explanationKo":"문맥상 「あやふや」가 가장 자연스럽다. 불분명함; 애매함; 흐지부지함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
