INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1707","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n部下を人前で（　）ような指導は適切ではない。","options":["腫れる","怒鳴る","漏れる","捕らえる"],"answer":"怒鳴る","explanationKo":"문맥상 「怒鳴る」가 가장 자연스럽다. 고함치다; 호통치다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2563","prompt":"「相手の意思に反して、無理に何かをさせる。」という意味に最も近い語を選びなさい。","options":["強いる","煙る","目覚める","付け加える"],"answer":"強いる","explanationKo":"「強いる」의 핵심 의미는 강요하다; 억지로 시키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2565","prompt":"「偶然その人・物を目にする。」という意味に最も近い語を選びなさい。","options":["申し出る","捕らえる","備え付ける","見掛ける"],"answer":"見掛ける","explanationKo":"「見掛ける」의 핵심 의미는 우연히 보다; 눈에 띄다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2571","prompt":"「一つのことを強く気にし、特に重視する。」という意味に最も近い語を選びなさい。","options":["研ぐ","凌ぐ","拘る","見落とす"],"answer":"拘る","explanationKo":"「拘る」의 핵심 의미는 집착하다; 고집하다; 세세하게 신경 쓰다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2596","prompt":"「方向・状態・話題などが別のものへ変わる、または変える。」という意味に最も近い語を選びなさい。","options":["書き取る","転じる","叶う","面する"],"answer":"転じる","explanationKo":"「転じる」의 핵심 의미는 바뀌다; 전환하다; 방향을 바꾸다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2601","prompt":"「勝負に金品などを出す。また、命・名誉などを危険にさらす覚悟をする。」という意味に最も近い語を選びなさい。","options":["賭ける","見落とす","掬う","治まる"],"answer":"賭ける","explanationKo":"「賭ける」의 핵심 의미는 걸다; 내기하다; 목숨 등을 걸다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','grammar',1,'〜ないものでもない','{"pattern":"〜ないものでもない","meaningKo":"못할 것도 없다","explanation":"〜ないものでもない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"条件を見直せば、協力できないものでもない。","ko":"문맥에서 못할 것도 없다의 의미로 쓰였다."},{"ja":"十分な時間があれば、完成させられないものでもない。","ko":"이 문장도 못할 것도 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','grammar',2,'〜なり','{"pattern":"〜なり","meaningKo":"〜하자마자","explanation":"〜なり는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は部屋に入るなり、結果を尋ねた。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"電話を切るなり、急いで資料を集め始めた。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n条件を見直せば、協力でき（　）。","options":["〜や否や","〜ないものでもない","〜にかかわる","〜べからざる"],"answer":"〜ないものでもない","explanationKo":"문맥상 못할 것도 없다를 나타내는 「〜ないものでもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は部屋に入る（　）、結果を尋ねた。","options":["〜なり","〜にしてからが","〜めく","〜だろうに"],"answer":"〜なり","explanationKo":"문맥상 〜하자마자를 나타내는 「〜なり」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一言（　）事前に知らせてほしかった。","options":["〜に忍びない","〜をおいて","〜てはかなわない","〜なりとも"],"answer":"〜なりとも","explanationKo":"문맥상 조금이라도를 나타내는 「〜なりとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-19','reading',1,'相談の前の整理','{"passage":"相談前に状況を整理することには、相手が問題を早く理解できることという利点がある。一方で、自分で結論を固定すると別の可能性を失うことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、事実と推測と希望を分けて伝えることが重要なのである。","questions":[{"prompt":"「相談の前の整理」について筆者が重視していることは何か。","options":["事実と推測と希望を分けて伝えること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"事実と推測と希望を分けて伝えること","explanationKo":"본문에서는 事実と推測と希望を分けて伝えること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["自分で結論を固定すると別の可能性を失うこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"自分で結論を固定すると別の可能性を失うこと","explanationKo":"주의점은 自分で結論を固定すると別の可能性を失うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["相手が問題を早く理解できること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"相手が問題を早く理解できること","explanationKo":"相談前に状況を整理すること에는 相手が問題を早く理解できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2635","prompt":"「研ぐ」の読み方として最も適切なものを選びなさい。","options":["なづける","しいれる","もうしいれる","とぐ"],"answer":"とぐ","explanationKo":"「研ぐ」는 「とぐ」라고 읽는다. 뜻은 갈다; 연마하다; 쌀을 씻다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
