INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1721","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今年の夏は暑かったが、八月後半は（　）厳しい暑さが続いた。","options":["終日","殊に","切ない","且つ"],"answer":"殊に","explanationKo":"문맥상 「殊に」가 가장 자연스럽다. 특히; 유난히라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1822","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n結論を出す前に、（　）関係者全員の意見は確認すべきだ。","options":["少なくとも","じっくり","至って","憂鬱"],"answer":"少なくとも","explanationKo":"문맥상 「少なくとも」가 가장 자연스럽다. 적어도; 최소한라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1841","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nログを確認したところ、（　）設定変更が障害の原因らしい。","options":["勤勉","猛烈","婉曲","どうやら"],"answer":"どうやら","explanationKo":"문맥상 「どうやら」가 가장 자연스럽다. 아무래도; 보아하니; 어떻게든라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1855","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予定どおり終えることも大切だが、安全を確保することが（　）重要だ。","options":["苛々","夥しい","何より","几帳面"],"answer":"何より","explanationKo":"문맥상 「何より」가 가장 자연스럽다. 무엇보다; 무엇보다도; 가장라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2649","prompt":"「うまくいくか、安全かなどについて不安・疑いを持つ。」という意味に最も近い語を選びなさい。","options":["綴じる","危ぶむ","折り返す","察する"],"answer":"危ぶむ","explanationKo":"「危ぶむ」의 핵심 의미는 위태롭게 여기다; 우려하다; 의심하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2651","prompt":"「人と人の間に入って、用件・電話などを相手へ伝える。」という意味に最も近い語を選びなさい。","options":["取り次ぐ","引っ掛ける","老いる","和らげる"],"answer":"取り次ぐ","explanationKo":"「取り次ぐ」의 핵심 의미는 전달하다; 중개하다; 전화를 연결하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2652","prompt":"「予定・時刻・進行などを後へずらす。」という意味に最も近い語を選びなさい。","options":["化ける","染まる","惜しむ","遅らす"],"answer":"遅らす","explanationKo":"「遅らす」의 핵심 의미는 늦추다; 지연시키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2654","prompt":"「山・建物などが非常に高く立つ。」という意味に最も近い語を選びなさい。","options":["組み合わせる","練る","聳える","引っ掛ける"],"answer":"聳える","explanationKo":"「聳える」의 핵심 의미는 우뚝 솟다; 높이 치솟다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2658","prompt":"「液体・色・味などが内部に入り込む。また、刺激や感情などが深く感じられる。」という意味に最も近い語を選びなさい。","options":["汚す","染みる","和らげる","落ち込む"],"answer":"染みる","explanationKo":"「染みる」의 핵심 의미는 스며들다; 배다; 사무치다; 따갑게 느껴지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','grammar',1,'〜なりとも','{"pattern":"〜なりとも","meaningKo":"조금이라도","explanation":"〜なりとも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"困っているなら、私になりとも相談してください。","ko":"문맥에서 조금이라도의 의미로 쓰였다."},{"ja":"一言なりとも事前に知らせてほしかった。","ko":"이 문장도 조금이라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','grammar',2,'〜なり〜なり','{"pattern":"〜なり〜なり","meaningKo":"〜든지 〜든지","explanation":"〜なり〜なり는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"電話なりメールなりで、必ず連絡してください。","ko":"문맥에서 〜든지 〜든지의 의미로 쓰였다."},{"ja":"賛成なり反対なり、自分の意見を明確にしてほしい。","ko":"이 문장도 〜든지 〜든지의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n困っているなら、私に（　）相談してください。","options":["〜なりとも","〜に忍びない","〜をおいて","〜てはかなわない"],"answer":"〜なりとも","explanationKo":"문맥상 조금이라도를 나타내는 「〜なりとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n電話（　）で、必ず連絡してください。","options":["〜にひきずられて","〜が最後","〜てはばからない","〜なり〜なり"],"answer":"〜なり〜なり","explanationKo":"문맥상 〜든지 〜든지를 나타내는 「〜なり〜なり」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一度の失敗だけで、彼を非難する（　）。","options":["〜かたわら","〜てまで","〜にあたらない","〜にもほどがある"],"answer":"〜にあたらない","explanationKo":"문맥상 〜할 것까지는 없다를 나타내는 「〜にあたらない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-20','reading',1,'試行を小さく始める','{"passage":"新しい方法を小規模に試すことには、失敗の影響を抑えながら学べることという利点がある。一方で、試行条件を記録しなければ結果を一般化できないことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、成功と失敗を判断する基準を先に置くことが重要なのである。","questions":[{"prompt":"「試行を小さく始める」について筆者が重視していることは何か。","options":["成功と失敗を判断する基準を先に置くこと","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"成功と失敗を判断する基準を先に置くこと","explanationKo":"본문에서는 成功と失敗を判断する基準を先に置くこと 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["試行条件を記録しなければ結果を一般化できないこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"試行条件を記録しなければ結果を一般化できないこと","explanationKo":"주의점은 試行条件を記録しなければ結果を一般化できないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["失敗の影響を抑えながら学べること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"失敗の影響を抑えながら学べること","explanationKo":"新しい方法を小規模に試すこと에는 失敗の影響を抑えながら学べること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2668","prompt":"「洒落る」の読み方として最も適切なものを選びなさい。","options":["しゃれる","おとろえる","なやます","はげむ"],"answer":"しゃれる","explanationKo":"「洒落る」는 「しゃれる」라고 읽는다. 뜻은 멋을 내다; 세련되게 꾸미다; 재치 있는 말을 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2677","prompt":"「似通う」の読み方として最も適切なものを選びなさい。","options":["すます","あきれる","うけつける","にかよう"],"answer":"にかよう","explanationKo":"「似通う」는 「にかよう」라고 읽는다. 뜻은 매우 닮다; 유사하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2680","prompt":"「剥ぐ」の読み方として最も適切なものを選びなさい。","options":["とだえる","そなえつける","はぐ","よわめる"],"answer":"はぐ","explanationKo":"「剥ぐ」는 「はぐ」라고 읽는다. 뜻은 벗기다; 떼어 내다; 가죽을 벗기다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1856","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼女は（　）耳がよく、小さな音の違いにもすぐ気づく。","options":["丸っきり","生まれつき","生臭い","少なくとも"],"answer":"生まれつき","explanationKo":"문맥상 「生まれつき」가 가장 자연스럽다. 타고나기를; 선천적으로; 천성적으로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1868","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n現在の進捗を見る限り、作業の完了は（　）来週になるだろう。","options":["恐らく","努めて","滑らか","物足りない"],"answer":"恐らく","explanationKo":"문맥상 「恐らく」가 가장 자연스럽다. 아마; 아마도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1883","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n数年ぶりに会ったが、彼は（　）忙しそうに働いていた。","options":["一様","貧弱","惨め","相変わらず"],"answer":"相変わらず","explanationKo":"문맥상 「相変わらず」가 가장 자연스럽다. 여전히; 변함없이; 예전과 마찬가지로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1947","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n異なる色の素材をうまく（　）と、印象的なデザインになる。","options":["察する","漏る","組み合わせる","騙す"],"answer":"組み合わせる","explanationKo":"문맥상 「組み合わせる」가 가장 자연스럽다. 조합하다; 짜 맞추다; 결합하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1952","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n子どものころから本に（　）習慣を身につけることは大切だ。","options":["洒落る","親しむ","連ねる","怯える"],"answer":"親しむ","explanationKo":"문맥상 「親しむ」가 가장 자연스럽다. 친숙해지다; 가까이하다; 즐겨 접하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1991","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n失敗を（　）だけでなく、原因を考えることが大切だ。","options":["嘆く","心掛ける","咎める","焦る"],"answer":"嘆く","explanationKo":"문맥상 「嘆く」가 가장 자연스럽다. 한탄하다; 슬퍼하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2031","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n終電に（　）間に合った。","options":["尊い","鈍感","未練","辛うじて"],"answer":"辛うじて","explanationKo":"문맥상 「辛うじて」가 가장 자연스럽다. 간신히; 가까스로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2682","prompt":"「物・人・連絡などを自分のいる側へ送る。」という意味に最も近い語を選びなさい。","options":["拘る","強請る","寄越す","偏る"],"answer":"寄越す","explanationKo":"「寄越す」의 핵심 의미는 보내다; 넘겨주다; 이쪽으로 보내오다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2687","prompt":"「相手に物や行為をしつこく求める。」という意味に最も近い語を選びなさい。","options":["慌てる","強請る","嘆く","交わる"],"answer":"強請る","explanationKo":"「強請る」의 핵심 의미는 조르다; 졸라 요구하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2690","prompt":"「意見や利害が合わず、争い・ごたごたが起こる。」という意味に最も近い語を選びなさい。","options":["揉める","偏る","拘る","寄越す"],"answer":"揉める","explanationKo":"「揉める」의 핵심 의미는 분쟁이 생기다; 다투다; 갈등하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2692","prompt":"「困っている人などに金品や恩恵を与える。」という意味に最も近い語を選びなさい。","options":["転じる","拵える","荒らす","恵む"],"answer":"恵む","explanationKo":"「恵む」의 핵심 의미는 베풀다; 은혜를 주다; 적선하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2699","prompt":"「物を下に垂れ下がるように掛ける。」という意味に最も近い語を選びなさい。","options":["叶える","聳える","ぶら下げる","寝かせる"],"answer":"ぶら下げる","explanationKo":"「ぶら下げる」의 핵심 의미는 매달다; 늘어뜨리다; 달랑거리게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','grammar',1,'〜にあたらない','{"pattern":"〜にあたらない","meaningKo":"〜할 것까지는 없다","explanation":"〜にあたらない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"予想された結果なので、驚くにはあたらない。","ko":"문맥에서 〜할 것까지는 없다의 의미로 쓰였다."},{"ja":"一度の失敗だけで、彼を非難するにはあたらない。","ko":"이 문장도 〜할 것까지는 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','grammar',2,'〜にかかわる','{"pattern":"〜にかかわる","meaningKo":"〜와 관련된 중대한","explanation":"〜にかかわる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"これは組織の信用にかかわる重大な問題だ。","ko":"문맥에서 〜와 관련된 중대한의 의미로 쓰였다."},{"ja":"安全にかかわる情報は速やかに共有すべきだ。","ko":"이 문장도 〜와 관련된 중대한의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n予想された結果なので、驚く（　）。","options":["〜にもほどがある","〜かたわら","〜てまで","〜にあたらない"],"answer":"〜にあたらない","explanationKo":"문맥상 〜할 것까지는 없다를 나타내는 「〜にあたらない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこれは組織の信用（　）重大な問題だ。","options":["〜がてら","〜といい〜といい","〜にかかわる","〜ばそれまでだ"],"answer":"〜にかかわる","explanationKo":"문맥상 〜와 관련된 중대한를 나타내는 「〜にかかわる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n基本方針（　）曖昧では、現場も判断できない。","options":["〜といったらありはしない","〜にしてからが","〜べからざる","〜がゆえに"],"answer":"〜にしてからが","explanationKo":"문맥상 〜부터가 이미를 나타내는 「〜にしてからが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-21','reading',1,'情報の鮮度を示す','{"passage":"情報の更新時点を示すことには、利用者が現在も有効か判断できることという利点がある。一方で、新しいという理由だけで正確とは限らないことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、取得日と確認方法を合わせて示すことが重要なのである。","questions":[{"prompt":"「情報の鮮度を示す」について筆者が重視していることは何か。","options":["取得日と確認方法を合わせて示すこと","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"取得日と確認方法を合わせて示すこと","explanationKo":"본문에서는 取得日と確認方法を合わせて示すこと 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["新しいという理由だけで正確とは限らないこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"新しいという理由だけで正確とは限らないこと","explanationKo":"주의점은 新しいという理由だけで正確とは限らないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["利用者が現在も有効か判断できること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"利用者が現在も有効か判断できること","explanationKo":"情報の更新時点を示すこと에는 利用者が現在も有効か判断できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2711","prompt":"「煙る」の読み方として最も適切なものを選びなさい。","options":["はげます","けむる","ねる","かなう"],"answer":"けむる","explanationKo":"「煙る」는 「けむる」라고 읽는다. 뜻은 연기가 나다; 연기로 흐려지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2721","prompt":"「霞む」の読み方として最も適切なものを選びなさい。","options":["かすむ","けがす","かきとる","はがす"],"answer":"かすむ","explanationKo":"「霞む」는 「かすむ」라고 읽는다. 뜻은 희미해지다; 뿌옇게 보이다; 흐려지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2723","prompt":"「澄ます」の読み方として最も適切なものを選びなさい。","options":["すくう","おさまる","そめる","すます"],"answer":"すます","explanationKo":"「澄ます」는 「すます」라고 읽는다. 뜻은 맑게 하다; 태연한 척하다; 새침한 표정을 짓다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2034","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n批判を感情的にならずに（　）必要がある。","options":["書き取る","剥がす","受け止める","面する"],"answer":"受け止める","explanationKo":"문맥상 「受け止める」가 가장 자연스럽다. 받아내다; 받아들이다; 이해하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2035","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は話が面白くて昔からよく（　）。","options":["罵る","持てる","掬う","治まる"],"answer":"持てる","explanationKo":"문맥상 「持てる」가 가장 자연스럽다. 인기가 있다; 호감을 받다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2053","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n運動をやめると体力は少しずつ（　）。","options":["衰える","妬む","連ねる","冴える"],"answer":"衰える","explanationKo":"문맥상 「衰える」가 가장 자연스럽다. 쇠하다; 약해지다; 쇠퇴하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2068","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n遠くから（　）な声が聞こえた。","options":["過多","即座に","不吉","微か"],"answer":"微か","explanationKo":"문맥상 「微か」가 가장 자연스럽다. 희미함; 어렴풋함; 미약함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2073","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）な着物の着こなしをしている。","options":["きっちり","一様","粋","華美"],"answer":"粋","explanationKo":"문맥상 「粋」가 가장 자연스럽다. 멋스러움; 세련됨; 멋진라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2080","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今年の売上は昨年を（　）勢いだ。","options":["重んじる","凌ぐ","乱す","面する"],"answer":"凌ぐ","explanationKo":"문맥상 「凌ぐ」가 가장 자연스럽다. 능가하다; 견디다; 넘기다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2087","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n将来について（　）とした不安を感じている。","options":["漠然","辛うじて","惨め","清々しい"],"answer":"漠然","explanationKo":"문맥상 「漠然」가 가장 자연스럽다. 막연함; 모호함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2728","prompt":"「物を作る。また、金・仕事・荷物などを用意する。」という意味に最も近い語を選びなさい。","options":["取り巻く","名付ける","重んじる","拵える"],"answer":"拵える","explanationKo":"「拵える」의 핵심 의미는 만들다; 마련하다; 꾸리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2729","prompt":"「液体・色などが広がる。また、感情などが表面に現れる。」という意味に最も近い語を選びなさい。","options":["賑わう","売り出す","滲む","葬る"],"answer":"滲む","explanationKo":"「滲む」의 핵심 의미는 번지다; 배어 나오다; 스미다; 어리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2734","prompt":"「水分を得て湿る。また、利益・恩恵を受けて豊かになる。」という意味に最も近い語を選びなさい。","options":["取り巻く","潤う","弄る","改まる"],"answer":"潤う","explanationKo":"「潤う」의 핵심 의미는 촉촉해지다; 풍요로워지다; 혜택을 보다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2735","prompt":"「実現や到来を強く期待して待つ。」という意味に最も近い語を選びなさい。","options":["待ち望む","澄ます","寝かせる","駆ける"],"answer":"待ち望む","explanationKo":"「待ち望む」의 핵심 의미는 손꼽아 기다리다; 고대하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2737","prompt":"「実施を一時控える。また、互いに顔を見合う。」という意味に最も近い語を選びなさい。","options":["弄る","改まる","待ち望む","見合わせる"],"answer":"見合わせる","explanationKo":"「見合わせる」의 핵심 의미는 보류하다; 연기하다; 서로 바라보다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','grammar',1,'〜にしてからが','{"pattern":"〜にしてからが","meaningKo":"〜부터가 이미","explanation":"〜にしてからが는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"責任者にしてからが規則を理解していない。","ko":"문맥에서 〜부터가 이미의 의미로 쓰였다."},{"ja":"基本方針にしてからが曖昧では、現場も判断できない。","ko":"이 문장도 〜부터가 이미의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','grammar',2,'〜に忍びない','{"pattern":"〜に忍びない","meaningKo":"차마 〜할 수 없다","explanation":"〜に忍びない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年使われた建物を壊すのは見るに忍びない。","ko":"문맥에서 차마 〜할 수 없다의 의미로 쓰였다."},{"ja":"努力してきた人に退職を求めるのは言うに忍びない。","ko":"이 문장도 차마 〜할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者（　）規則を理解していない。","options":["〜がゆえに","〜といったらありはしない","〜にしてからが","〜べからざる"],"answer":"〜にしてからが","explanationKo":"문맥상 〜부터가 이미를 나타내는 「〜にしてからが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年使われた建物を壊すのは見る（　）。","options":["〜としたところで","〜に忍びない","〜めく","〜ごとく"],"answer":"〜に忍びない","explanationKo":"문맥상 차마 〜할 수 없다를 나타내는 「〜に忍びない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n周囲の雰囲気（　）、十分な検討を怠った。","options":["〜にひきずられて","〜をおいて","〜や否や","〜ともあろうものが"],"answer":"〜にひきずられて","explanationKo":"문맥상 〜에 끌려서를 나타내는 「〜にひきずられて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-22','reading',1,'担当者に依存しない仕組み','{"passage":"業務知識を共有することには、担当変更後も判断を継続できることという利点がある。一方で、手順だけでは例外時の理由が伝わらないことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、判断の根拠と確認先も残すことが重要なのである。","questions":[{"prompt":"「担当者に依存しない仕組み」について筆者が重視していることは何か。","options":["判断の根拠と確認先も残すこと","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"判断の根拠と確認先も残すこと","explanationKo":"본문에서는 判断の根拠と確認先も残すこと 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["手順だけでは例外時の理由が伝わらないこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"手順だけでは例外時の理由が伝わらないこと","explanationKo":"주의점은 手順だけでは例外時の理由が伝わらないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["担当変更後も判断を継続できること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"担当変更後も判断を継続できること","explanationKo":"業務知識を共有すること에는 担当変更後も判断を継続できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2149","prompt":"「取り巻く」の読み方として最も適切なものを選びなさい。","options":["とじる","もめる","とりまく","さっする"],"answer":"とりまく","explanationKo":"「取り巻く」는 「とりまく」라고 읽는다. 뜻은 둘러싸다; 에워싸다; 주변을 둘러싼이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
