INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2175","prompt":"「脱する」の読み方として最も適切なものを選びなさい。","options":["だっする","たちよる","えんじる","けがす"],"answer":"だっする","explanationKo":"「脱する」는 「だっする」라고 읽는다. 뜻은 벗어나다; 탈피하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2181","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n山から（　）な水が流れている。","options":["心細い","簡潔","微か","清らか"],"answer":"清らか","explanationKo":"문맥상 「清らか」가 가장 자연스럽다. 맑고 깨끗함; 순수함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2185","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n隣の工事の音が朝から（　）。","options":["簡潔","ぶらぶら","喧しい","慌ただしい"],"answer":"喧しい","explanationKo":"문맥상 「喧しい」가 가장 자연스럽다. 시끄럽다; 까다롭다; 엄격하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2210","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n本人は（　）元気そうだった。","options":["切ない","至って","渋い","不順"],"answer":"至って","explanationKo":"문맥상 「至って」가 가장 자연스럽다. 지극히; 매우; 아주라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2212","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nりんごを皮ごと（　）食べた。","options":["丸ごと","何卒","即座に","明瞭"],"answer":"丸ごと","explanationKo":"문맥상 「丸ごと」가 가장 자연스럽다. 통째로; 전부라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2215","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域では昔から自然を（　）文化がある。","options":["乗り込む","強まる","病む","尊ぶ"],"answer":"尊ぶ","explanationKo":"문맥상 「尊ぶ」가 가장 자연스럽다. 존중하다; 귀하게 여기다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2232","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な表現だが、健康が一番大切だ。","options":["諄い","相変わらず","月並み","無茶苦茶"],"answer":"月並み","explanationKo":"문맥상 「月並み」가 가장 자연스럽다. 평범함; 진부함; 매달 정례라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2234","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n試験に落ちたと知って、彼は（　）肩を落とした。","options":["見苦しい","がっくり","恐らく","過多"],"answer":"がっくり","explanationKo":"문맥상 「がっくり」가 가장 자연스럽다. 풀이 죽어; 크게 실망하여; 푹라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2236","prompt":"「過ち・失敗などを責める。また、傷などの状態が悪くなる意味もある。」という意味に最も近い語を選びなさい。","options":["咎める","賑わう","代わる","親しむ"],"answer":"咎める","explanationKo":"「咎める」의 핵심 의미는 나무라다; 책망하다; 문제 삼다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2249","prompt":"「整っている状態・秩序・心などを乱れた状態にする。」という意味に最も近い語を選びなさい。","options":["途絶える","備え付ける","引き取る","乱す"],"answer":"乱す","explanationKo":"「乱す」의 핵심 의미는 흐트러뜨리다; 어지럽히다; 혼란시키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2253","prompt":"「心身が健康で、元気に成長・生活しているさま。」という意味に最も近い語を選びなさい。","options":["安っぽい","生まれつき","健やか","長大"],"answer":"健やか","explanationKo":"「健やか」의 핵심 의미는 건강함; 튼튼함; 건전함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2254","prompt":"「線などが交差する。また、人と付き合い、交流する。」という意味に最も近い語を選びなさい。","options":["危ぶむ","交わる","挑む","漏る"],"answer":"交わる","explanationKo":"「交わる」의 핵심 의미는 교차하다; 어울리다; 교류하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2262","prompt":"「態度・発言などを迷いなく、はっきりと示すさま。」という意味に最も近い語を選びなさい。","options":["きっぱり","夥しい","薄弱","何より"],"answer":"きっぱり","explanationKo":"「きっぱり」의 핵심 의미는 단호하게; 딱 잘라; 명확하게이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','grammar',1,'〜にひきずられて','{"pattern":"〜にひきずられて","meaningKo":"〜에 끌려서","explanation":"〜にひきずられて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"目先の利益にひきずられて、長期的な価値を失ってはいけない。","ko":"문맥에서 〜에 끌려서의 의미로 쓰였다."},{"ja":"周囲の雰囲気にひきずられて、十分な検討を怠った。","ko":"이 문장도 〜에 끌려서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','grammar',2,'〜にもほどがある','{"pattern":"〜にもほどがある","meaningKo":"〜에도 정도가 있다","explanation":"〜にもほどがある는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"連絡もなく二時間遅れるとは、無責任にもほどがある。","ko":"문맥에서 〜에도 정도가 있다의 의미로 쓰였다."},{"ja":"事実を確認せず批判するのは、軽率にもほどがある。","ko":"이 문장도 〜에도 정도가 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n目先の利益（　）、長期的な価値を失ってはいけない。","options":["〜ともあろうものが","〜にひきずられて","〜をおいて","〜や否や"],"answer":"〜にひきずられて","explanationKo":"문맥상 〜에 끌려서를 나타내는 「〜にひきずられて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n連絡もなく二時間遅れるとは、無責任（　）。","options":["〜にもほどがある","〜が最後","〜だろうに","〜ないものでもない"],"answer":"〜にもほどがある","explanationKo":"문맥상 〜에도 정도가 있다를 나타내는 「〜にもほどがある」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n本人の努力不足だと片づけれ（　）が、制度にも問題がある。","options":["〜かたわら","〜てはかなわない","〜なり","〜ばそれまでだ"],"answer":"〜ばそれまでだ","explanationKo":"문맥상 〜하면 그것으로 끝이다를 나타내는 「〜ばそれまでだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-23','reading',1,'反復学習の調整','{"passage":"同じ内容を繰り返し学ぶことには、忘れかけた知識を強化できることという利点がある。一方で、理解済みの項目だけ続けると弱点が残ることも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、記憶状態に応じて間隔と内容を変えることが重要なのである。","questions":[{"prompt":"「反復学習の調整」について筆者が重視していることは何か。","options":["記憶状態に応じて間隔と内容を変えること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"記憶状態に応じて間隔と内容を変えること","explanationKo":"본문에서는 記憶状態に応じて間隔と内容を変えること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["理解済みの項目だけ続けると弱点が残ること","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"理解済みの項目だけ続けると弱点が残ること","explanationKo":"주의점은 理解済みの項目だけ続けると弱点が残ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["忘れかけた知識を強化できること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"忘れかけた知識を強化できること","explanationKo":"同じ内容を繰り返し学ぶこと에는 忘れかけた知識を強化できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2296","prompt":"「冷酷」の読み方として最も適切なものを選びなさい。","options":["ろこつ","せいこう","たくましい","れいこく"],"answer":"れいこく","explanationKo":"「冷酷」는 「れいこく」라고 읽는다. 뜻은 냉혹함; 인정사정없음; 매정함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
