INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2304","prompt":"「容易い」の読み方として最も適切なものを選びなさい。","options":["きらびやか","たやすい","まえもって","なにとぞ"],"answer":"たやすい","explanationKo":"「容易い」는 「たやすい」라고 읽는다. 뜻은 쉽다; 용이하다; 손쉽다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2305","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n原材料費の上昇で、各社の商品価格が（　）上がった。","options":["軒並み","煌びやか","酷い","丸々"],"answer":"軒並み","explanationKo":"문맥상 「軒並み」가 가장 자연스럽다. 집들이 줄지어 있음; 하나같이; 모조리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2307","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n夕方に（　）ころ、急に雨が降り始めた。","options":["盛り上がる","備わる","怒鳴る","差し掛かる"],"answer":"差し掛かる","explanationKo":"문맥상 「差し掛かる」가 가장 자연스럽다. 접어들다; 다다르다; 가까워지다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2310","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの薬には痛みを（　）効果がある。","options":["染まる","惜しむ","和らげる","拵える"],"answer":"和らげる","explanationKo":"문맥상 「和らげる」가 가장 자연스럽다. 누그러뜨리다; 완화하다; 덜어 주다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2312","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）一つ選ぶなら、この案が最も現実的だ。","options":["きっちり","強いて","丸ごと","鬱陶しい"],"answer":"強いて","explanationKo":"문맥상 「強いて」가 가장 자연스럽다. 굳이; 억지로; 강제로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2318","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今後とも（　）よろしくお願い申し上げます。","options":["何卒","今更","生まれつき","先だって"],"answer":"何卒","explanationKo":"문맥상 「何卒」가 가장 자연스럽다. 아무쪼록; 부디; 제발라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2327","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n業務に（　）ほどの体調不良なら、無理せず休んでください。","options":["滲む","苦しめる","沈める","差し支える"],"answer":"差し支える","explanationKo":"문맥상 「差し支える」가 가장 자연스럽다. 지장을 주다; 방해가 되다; 곤란을 초래하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2331","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n前の仕事に（　）はなく、新しい環境で頑張りたい。","options":["がっくり","鬱陶しい","未練","下らない"],"answer":"未練","explanationKo":"문맥상 「未練」가 가장 자연스럽다. 미련; 아쉬움; 마음을 떨치지 못함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2334","prompt":"「物を引きずるさま。また、好ましくない状態をはっきり終わらせず長引かせるさま。」という意味に最も近い語を選びなさい。","options":["ぶらぶら","ずるずる","惨め","華美"],"answer":"ずるずる","explanationKo":"「ずるずる」의 핵심 의미는 질질; 계속 미루며; 흐지부지 계속이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2341","prompt":"「数量・程度が非常に多い、または甚だしい。」という意味に最も近い語を選びなさい。","options":["夥しい","安っぽい","待ち遠しい","円滑"],"answer":"夥しい","explanationKo":"「夥しい」의 핵심 의미는 엄청나게 많다; 수없이 많다; 막대하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2342","prompt":"「雰囲気・表情などが穏やかで、打ち解けているさま。」という意味に最も近い語を選びなさい。","options":["ぞんざい","渋い","下らない","和やか"],"answer":"和やか","explanationKo":"「和やか」의 핵심 의미는 화기애애하다; 온화하다; 부드럽고 평온하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2349","prompt":"「品性・言動などが下品で、品位に欠ける。また、欲深く浅ましい。」という意味に最も近い語を選びなさい。","options":["至って","精巧","卑しい","くっきり"],"answer":"卑しい","explanationKo":"「卑しい」의 핵심 의미는 천하다; 상스럽다; 비열하다; 탐욕스럽다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2358","prompt":"「細部までよく作られていて、非常に巧みで精密なさま。」という意味に最も近い語を選びなさい。","options":["温和","精巧","ちょくちょく","慌ただしい"],"answer":"精巧","explanationKo":"「精巧」의 핵심 의미는 정교함; 매우 섬세하고 치밀함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','grammar',1,'〜ばそれまでだ','{"pattern":"〜ばそれまでだ","meaningKo":"〜하면 그것으로 끝이다","explanation":"〜ばそれまでだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"規則だから仕方ないと言ってしまえばそれまでだ。","ko":"문맥에서 〜하면 그것으로 끝이다의 의미로 쓰였다."},{"ja":"本人の努力不足だと片づければそれまでだが、制度にも問題がある。","ko":"이 문장도 〜하면 그것으로 끝이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','grammar',2,'〜べからざる','{"pattern":"〜べからざる","meaningKo":"〜해서는 안 되는","explanation":"〜べからざる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"個人情報の漏えいは、あってはならない許すべからざる行為だ。","ko":"문맥에서 〜해서는 안 되는의 의미로 쓰였다."},{"ja":"証拠の改ざんは、研究者として許すべからざる行為である。","ko":"이 문장도 〜해서는 안 되는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n規則だから仕方ないと言ってしまえ（　）。","options":["〜ばそれまでだ","〜かたわら","〜てはかなわない","〜なり"],"answer":"〜ばそれまでだ","explanationKo":"문맥상 〜하면 그것으로 끝이다를 나타내는 「〜ばそれまでだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n個人情報の漏えいは、あってはならない許す（　）行為だ。","options":["〜がてら","〜てはばからない","〜なりとも","〜べからざる"],"answer":"〜べからざる","explanationKo":"문맥상 〜해서는 안 되는를 나타내는 「〜べからざる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は冗談（　）口調で本音を語った。","options":["〜てまで","〜なり〜なり","〜めく","〜がゆえに"],"answer":"〜めく","explanationKo":"문맥상 〜다운 기운을 띠다를 나타내는 「〜めく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-24','reading',1,'公共空間の規則','{"passage":"公共空間の利用規則を設けることには、異なる利用者の衝突を減らせることという利点がある。一方で、禁止だけ増やすと本来の利用価値を損なうことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、守る利益と制限の程度を比較することが重要なのである。","questions":[{"prompt":"「公共空間の規則」について筆者が重視していることは何か。","options":["守る利益と制限の程度を比較すること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"守る利益と制限の程度を比較すること","explanationKo":"본문에서는 守る利益と制限の程度を比較すること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["禁止だけ増やすと本来の利用価値を損なうこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"禁止だけ増やすと本来の利用価値を損なうこと","explanationKo":"주의점은 禁止だけ増やすと本来の利用価値を損なうこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["異なる利用者の衝突を減らせること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"異なる利用者の衝突を減らせること","explanationKo":"公共空間の利用規則を設けること에는 異なる利用者の衝突を減らせること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2463","prompt":"「且つ」の読み方として最も適切なものを選びなさい。","options":["かつ","ふさわしい","やすっぽい","しきりに"],"answer":"かつ","explanationKo":"「且つ」는 「かつ」라고 읽는다. 뜻은 그리고; 또한; 동시에이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
