INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2607","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその話は（　）の嘘だった。","options":["丸っきり","きちっと","円滑","快い"],"answer":"丸っきり","explanationKo":"문맥상 「丸っきり」가 가장 자연스럽다. 완전히; 전혀; 도무지라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
