INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2620","prompt":"「心に深く感じ入るさま。じっくりと味わうさま。」という意味に最も近い語を選びなさい。","options":["長大","丸々","しみじみ","過多"],"answer":"しみじみ","explanationKo":"「しみじみ」의 핵심 의미는 절실히; 새삼스럽게; 깊이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2634","prompt":"「非常に華やかで目立ち、立派である。」という意味に最も近い語を選びなさい。","options":["頑丈","華々しい","渋い","清々しい"],"answer":"華々しい","explanationKo":"「華々しい」의 핵심 의미는 화려하다; 눈부시다; 장대하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2657","prompt":"「その時・出来事が早く来てほしいと強く期待する。」という意味に最も近い語を選びなさい。","options":["待ち遠しい","到底","悲惨","少なくとも"],"answer":"待ち遠しい","explanationKo":"「待ち遠しい」의 핵심 의미는 손꼽아 기다려지다; 몹시 기다려지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2679","prompt":"「よく考えず、度を越して行うさま。」という意味に最も近い語を選びなさい。","options":["精密","善良","和やか","無闇に"],"answer":"無闇に","explanationKo":"「無闇に」의 핵심 의미는 함부로; 무턱대고; 마구이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2706","prompt":"「華やかで、きらきらと美しく目立つさま。」という意味に最も近い語を選びなさい。","options":["先だって","過密","煌びやか","鬱陶しい"],"answer":"煌びやか","explanationKo":"「煌びやか」의 핵심 의미는 화려하다; 눈부시게 아름답다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','grammar',1,'〜めく','{"pattern":"〜めく","meaningKo":"〜다운 기운을 띠다","explanation":"〜めく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"風が暖かくなり、辺りはすっかり春めいてきた。","ko":"문맥에서 〜다운 기운을 띠다의 의미로 쓰였다."},{"ja":"彼は冗談めいた口調で本音を語った。","ko":"이 문장도 〜다운 기운을 띠다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','grammar',2,'〜をおいて','{"pattern":"〜をおいて","meaningKo":"〜외에는","explanation":"〜をおいて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この難しい交渉を任せられるのは彼をおいてほかにいない。","ko":"문맥에서 〜외에는의 의미로 쓰였다."},{"ja":"今の状況を変える機会は今回をおいてほかにない。","ko":"이 문장도 〜외에는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n風が暖かくなり、辺りはすっかり春（　）きた。","options":["〜がゆえに","〜てまで","〜なり〜なり","〜めく"],"answer":"〜めく","explanationKo":"문맥상 〜다운 기운을 띠다를 나타내는 「〜めく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの難しい交渉を任せられるのは彼（　）ほかにいない。","options":["〜といい〜といい","〜にあたらない","〜をおいて","〜ごとく"],"answer":"〜をおいて","explanationKo":"문맥상 〜외에는를 나타내는 「〜をおいて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその秘密を口にした（　）、以前の関係には戻れない。","options":["〜にかかわる","〜が最後","〜や否や","〜といったらありはしない"],"answer":"〜が最後","explanationKo":"문맥상 〜하면 그것으로 끝를 나타내는 「〜が最後」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-25','reading',1,'撤退基準を決める','{"passage":"計画の中止条件を定めることには、損失が広がる前に方針を変えられることという利点がある。一方で、短期の不振だけで判断すると成長機会を失うことも忘れてはならない。実施する際には目的と条件を共有し、結果が想定と異なる場合に見直せるよう記録を残す必要がある。つまり、期間と指標を組み合わせて判断することが重要なのである。","questions":[{"prompt":"「撤退基準を決める」について筆者が重視していることは何か。","options":["期間と指標を組み合わせて判断すること","最初の方法を変更しないこと","結果を記録しないこと","条件を示さず結論だけ伝えること"],"answer":"期間と指標を組み合わせて判断すること","explanationKo":"본문에서는 期間と指標を組み合わせて判断すること 것이 중요하다고 말한다."},{"prompt":"本文で注意点として述べられているものは何か。","options":["短期の不振だけで判断すると成長機会を失うこと","利点が必ず消えること","関係者が不要になること","目的が自動的に決まること"],"answer":"短期の不振だけで判断すると成長機会を失うこと","explanationKo":"주의점은 短期の不振だけで判断すると成長機会を失うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["損失が広がる前に方針を変えられること","想定と違っても見直してはならない","目的を共有する必要はない","記録は判断を妨げる"],"answer":"損失が広がる前に方針を変えられること","explanationKo":"計画の中止条件を定めること에는 損失が広がる前に方針を変えられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
